insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v001', 'abundant', 'Về quê ba ngày, mẹ gói đồ ăn ABUNDANT đỉnh nóc kịch trần, cả dãy trọ ăn ké, chủ trọ cũng ghé xin một hộp.', 'Dư thừa, nhiều hơn cần thiết', 'beginner', 850),
  ('v002', 'cognitive', 'Ôn thi xuyên đêm tới 4 giờ sáng, khả năng COGNITIVE còn đủ đọc tên môn, đề hỏi gì thì toang.', 'Liên quan đến nhận thức, tri giác', 'beginner', 870),
  ('v003', 'dilemma', 'DILEMMA cuối tháng: còn 50 nghìn, mua cơm cho no hay mua trà sữa cho đỡ chằm zn vì nghèo.', 'Tình huống khó xử, lưỡng nan', 'beginner', 820),
  ('v004', 'feasible', 'Kế hoạch học xong ba chương trong một đêm nghe không FEASIBLE lắm, nhưng cả nhóm vẫn hô gét gô.', 'Khả thi, có thể thực hiện được', 'beginner', 880),
  ('v005', 'inevitable', 'Lướt app mua sắm lúc nửa đêm thì chốt đơn là INEVITABLE, sáng ra mới hỏi mua máy làm bánh để làm gì, u là trời.', 'Không thể tránh khỏi', 'beginner', 890),
  ('v006', 'pragmatic', 'Bạn mình PRAGMATIC lắm, đi date chọn quán có ổ cắm với wifi mạnh, tình chưa tới nhưng pin thì đầy, ra đường tôi nể mỗi bạn.', 'Thực dụng, thực tế', 'beginner', 920),
  ('v007', 'ambiguous', 'Crush thả tim story rồi seen tin nhắn ba ngày, AMBIGUOUS cỡ này thì delulu cũng phải nghỉ giữa hiệp.', 'Mơ hồ, không rõ ràng', 'beginner', 950),
  ('v008', 'resilient', 'Nhỏ bạn RESILIENT thật, trưa bị từ chối tỏ tình, tối đã đăng story caption chữa lành kèm ly matcha.', 'Kiên cường, phục hồi nhanh', 'beginner', 940),
  ('v009', 'tedious', 'Ngồi gõ điểm danh 200 người từ ảnh chụp vào Excel, việc TEDIOUS tới mức con mắt xin nghỉ phép, ét o ét.', 'Buồn tẻ, nhàm chán', 'beginner', 910),
  ('v010', 'subtle', 'Mẹ khen ''dạo này con có da có thịt ha'', lời nhắc SUBTLE rằng Tết này bớt đụng vô nồi bánh chưng, ok mom.', 'Tinh tế, khó nhận ra', 'beginner', 930),
  ('v011', 'meticulous', 'Nhỏ bàn trên METICULOUS tới mức note ôn thi có bốn màu bút với mục lục, keo lỳ thật, mình xin photo mà muốn lạy.', 'Tỉ mỉ, cẩn thận', 'intermediate', 1050),
  ('v012', 'ubiquitous', 'Bài nhạc trend đó giờ UBIQUITOUS thật, từ TikTok tới quán phở đầu hẻm đều bật, tối nằm mơ cũng nghe, u là trời.', 'Phổ biến khắp nơi', 'intermediate', 1080),
  ('v013', 'ephemeral', 'Cảm giác được chữa lành sau chuyến Đà Lạt EPHEMERAL thật, sáng thứ Hai mở mail ra là bay sạch.', 'Phù du, ngắn ngủi', 'intermediate', 1100),
  ('v014', 'eloquent', 'Bình thường nói chuyện ấp úng, mà tới lúc xin mẹ tiền mua laptop là ELOQUENT như diễn giả, out trình cả thầy dạy thuyết trình.', 'Hùng biện, lưu loát', 'intermediate', 1020),
  ('v015', 'plausible', '''Xe tao xẹp lốp'' là lý do PLAUSIBLE, nếu story của nó không đang check-in quán nướng, ủa alo.', 'Hợp lý, đáng tin', 'intermediate', 1010),
  ('v016', 'scrutinize', 'Người yêu cũ đăng ảnh mới là cả group SCRUTINIZE từng pixel, check var còn kỹ hơn chấm thi.', 'Xem xét kỹ lưỡng', 'intermediate', 1040),
  ('v017', 'candid', 'Nhờ bạn thân nhận xét CANDID về outfit đi date, nó phán ''kém miếng khó chịu'', giờ mình đang thay bộ thứ năm.', 'Thẳng thắn, chân thành', 'intermediate', 1030),
  ('v018', 'contemplate', 'Nằm CONTEMPLATE nửa tiếng xem nên dậy hay ngủ tiếp, cuối cùng ngủ tiếp vì nghĩ nhiều lowkey mệt quá.', 'Suy ngẫm, trầm tư', 'intermediate', 1060),
  ('v019', 'mundane', 'Đi làm năm nhất delulu tưởng được đụng dự án lớn, ai ngờ ngày nào cũng việc MUNDANE: photo, scan, pha cà phê.', 'Tầm thường, nhàm chán', 'intermediate', 1000),
  ('v020', 'inherent', 'Ở trọ thì phòng bên hát karaoke lúc 11 giờ đêm là rủi ro INHERENT, hợp đồng không ghi mà ai cũng biết, real.', 'Vốn có, cố hữu', 'intermediate', 1070),
  ('v021', 'conundrum', 'CONUNDRUM mỗi sáng: dậy sớm thì buồn ngủ cả ngày, dậy muộn thì trễ học, còn ngủ sớm thì chưa từng, hết cứu.', 'Vấn đề hóc búa', 'intermediate', 1150),
  ('v022', 'exacerbate', 'Thi rớt xong mở TikTok toàn clip người ta flex học bổng, càng lướt càng EXACERBATE nỗi đau.', 'Làm tệ hại thêm', 'intermediate', 1180),
  ('v023', 'mitigate', 'Hai ly cà phê đá chỉ MITIGATE được cơn buồn ngủ tới 10 giờ, sau đó vẫn gục lên bàn phím như cũ, toang.', 'Giảm nhẹ, làm dịu', 'intermediate', 1120),
  ('v024', 'nuance', 'Phải hiểu NUANCE giữa ''ok'' và ''okk'' trong tin nhắn crush, sai một chữ k là cả tối nằm check var như trọng tài.', 'Sắc thái nhỏ', 'intermediate', 1140),
  ('v025', 'prolific', 'Đứa em họ PROLIFIC thật, một tuần đăng 20 video TikTok, còn mình một video edit chưa xong, bị out trình.', 'Hiệu suất cao, đẻ nhiều', 'intermediate', 1160),
  ('v026', 'redundant', 'Mua sạc dự phòng thứ ba trong năm, balo giờ toàn đồ REDUNDANT mà điện thoại vẫn sập nguồn, xu cà na gì đâu.', 'Thừa thãi', 'intermediate', 1110),
  ('v027', 'tangible', 'Ba tháng đi gym, kết quả TANGIBLE duy nhất để flex là cái thẻ hội viên, cái bụng thì vẫn y chang.', 'Hữu hình, rõ rệt', 'intermediate', 1130),
  ('v028', 'zenith', 'ZENITH đời sinh viên là tuần nhận học bổng, ăn lẩu ba bữa liền như đại gia, sau đó là chuỗi ngày mì gói, toang.', 'Đỉnh cao', 'intermediate', 1190),
  ('v029', 'coherent', 'Ba giờ sáng gửi crush một đoạn văn ô dề mà chẳng COHERENT tí nào, sáng dậy đọc lại muốn đổi luôn tên Zalo.', 'Mạch lạc, logic', 'intermediate', 1170),
  ('v030', 'arbitrary', 'Cách thầy chấm thuyết trình nghe ARBITRARY quá, nhóm làm ba tuần được 7, nhóm làm ba tiếng được 9, đòi check var gấp.', 'Tùy hứng, tùy tiện', 'intermediate', 1100),
  ('v031', 'belligerent', 'Chưa ăn sáng là bạn cùng phòng BELLIGERENT liền, hỏi ''mày ổn không'' cũng bị lườm như kẻ thù, tới công chuyện.', 'Hiếu chiến, hung hăng', 'advanced', 1250),
  ('v032', 'elucidate', 'Nhờ bạn học giỏi ELUCIDATE lại bài đạo hàm, nó giảng mười phút, mình chỉ hiểu ra là mình hết cứu.', 'Làm sáng tỏ, giải thích rõ', 'advanced', 1220),
  ('v033', 'esoteric', 'Group chat có mấy inside joke ESOTERIC tới mức người mới vào đọc ba ngày vẫn tưởng mật mã, fomo muốn khóc.', 'Bí truyền, chuyên sâu khó hiểu', 'advanced', 1280),
  ('v034', 'gregarious', 'Nhỏ bạn GREGARIOUS tới mức đi vệ sinh ở quán cà phê ra đã có thêm hai người bạn và một nhóm Zalo, ra đường tôi nể mỗi bạn.', 'Hòa đồng, thích giao du', 'advanced', 1240),
  ('v035', 'impetuous', 'Một phút IMPETUOUS tự báo thủ mái tóc theo trend TikTok, giờ đi học phải đội mũ lưỡi trai cả tuần.', 'Hấp tấp, bốc đồng', 'advanced', 1260),
  ('v036', 'juxtapose', 'Thử JUXTAPOSE ảnh mẫu trên shop với bộ đồ giao tới, thấy rõ hai vũ trụ song song, u là trời.', 'Đặt cạnh nhau để so sánh', 'advanced', 1230),
  ('v037', 'malevolent', 'Con mèo nhìn ly cà phê trên bàn bằng ánh mắt MALEVOLENT, ba giây sau bàn phím laptop ướt sũng, báo thủ chính hiệu.', 'Độc ác, có ác ý', 'advanced', 1270),
  ('v038', 'obfuscate', 'Hỏi ''hôm qua đi đâu'' mà người yêu trả lời vòng vo ba đoạn, cố OBFUSCATE kiểu này là red flag rồi.', 'Làm mờ mịt, che giấu', 'advanced', 1290),
  ('v039', 'parsimony', 'PARSIMONY của thằng bạn đỉnh nóc kịch trần, đi chơi năm lần thì đúng năm lần nó quên ví.', 'Sự bủn xỉn, keo kiệt', 'advanced', 1210),
  ('v040', 'quintessential', 'Ngồi ghế nhựa ăn bánh tráng trộn, uống trà đá, hóng biến group lớp, một buổi chiều QUINTESSENTIAL của sinh viên.', 'Tinh túy, điển hình', 'advanced', 1200)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v041', 'recalcitrant', 'Mái tóc RECALCITRANT này sấy, uốn, xịt keo đủ kiểu vẫn dựng đứng y như vừa ngủ dậy, hết cứu.', 'Ngoan cố, bướng bỉnh', 'expert', 1350),
  ('v042', 'salient', 'Điểm SALIENT nhất trong profile hẹn hò của nó là tấm ảnh ôm chó, mà con chó là của hàng xóm, red flag.', 'Nổi bật, đáng chú ý', 'expert', 1320),
  ('v043', 'taciturn', 'Về quê ăn Tết, mình TACITURN cả buổi, bị hỏi lương bao nhiêu mới chằm zn nói đúng ba chữ ''cũng tạm ạ''.', 'Ít nói, lầm lì', 'expert', 1340),
  ('v044', 'vicarious', 'Ví cạn nên du lịch kiểu VICARIOUS, coi vlog Nhật tới 2 giờ sáng, manifest xong ngủ như vừa đi về.', 'Trải nghiệm gián tiếp', 'expert', 1310),
  ('v045', 'zealot', 'Nhỏ bạn là ZEALOT của trà sữa, ai chê trân châu đường đen là kick khỏi group liền, ô dề hết sức.', 'Người cuồng tín', 'expert', 1330),
  ('v046', 'ameliorate', 'Sắm cây xanh, đèn vàng, nến thơm để AMELIORATE phòng trọ 12 mét vuông, giờ chật hơn nhưng lowkey xinh.', 'Cải thiện, làm tốt hơn', 'expert', 1360),
  ('v047', 'cacophony', 'Bảy giờ sáng Chủ nhật: khoan tường, gà gáy, loa bán hàng, một bản CACOPHONY ngay trên đầu phòng trọ, tới công chuyện.', 'Âm thanh hỗn tạp, chói tai', 'expert', 1380),
  ('v048', 'dogmatic', 'Ông chú DOGMATIC tới mức tin học IT là phải sửa được tủ lạnh, giải thích cỡ nào cũng không nghe, xỉu ngang.', 'Giáo điều, độc đoán', 'expert', 1300),
  ('v049', 'enervate', 'Ba tiếng xếp hàng săn vé concert vì fomo đủ ENERVATE cả người, mua được vé xong ngồi bệt luôn ra vỉa hè.', 'Làm suy yếu, làm kiệt sức', 'expert', 1390),
  ('v050', 'hackneyed', 'Caption ''đi đâu không quan trọng, quan trọng là đi với ai'' HACKNEYED lắm rồi, mà đi biển lần nào mình cũng xài, real.', 'Sáo rỗng, tầm thường', 'expert', 1410),
  ('v051', 'grandiloquent', 'Bài luận học bổng viết GRANDILOQUENT như diễn văn, đọc ba trang mới thấy ý chính là ''em cần tiền'', ô dề ghê.', 'Khoa trương, hoa mỹ', 'expert', 1450),
  ('v052', 'iconoclast', 'Đứa ICONOCLAST của nhóm dám nói lẩu Thái dở, cả bàn im bặt như vừa nghe tin chia tay, ra đường tôi nể mỗi bạn.', 'Người đả phá những quan điểm cũ', 'expert', 1440),
  ('v053', 'laconic', 'Gửi crush một tin dài 500 chữ, nhận về câu trả lời LACONIC đúng một chữ ''ok'', đọc xong xỉu ngang.', 'Ngắn gọn, súc tích', 'expert', 1430),
  ('v054', 'obsequious', 'Tuần trước thi cả lớp OBSEQUIOUS với lớp trưởng lạ thường, mời trà sữa liên tục để xin đề cương, thao túng tâm lý.', 'Khúm núm, xu nịnh', 'expert', 1460),
  ('v055', 'pernicious', 'Thói quen ''xem thêm một tập thôi'' PERNICIOUS hơn mình tưởng, giờ đã hết season ba và trời đã sáng, toang.', 'Độc hại, nguy hiểm ngầm', 'expert', 1470),
  ('v056', 'quixotic', 'Kế hoạch mua nhà bằng lương thực tập 3 triệu nghe QUIXOTIC quá, nhưng tối nào mình cũng manifest.', 'Viển vông, không thực tế', 'expert', 1480),
  ('v057', 'risible', 'Bài thuyết trình nhóm RISIBLE tới mức slide 3 còn nguyên dòng ''chèn nội dung vào đây'', ét o ét.', 'Đáng cười, lố bịch', 'expert', 1400),
  ('v058', 'sycophant', 'Group lớp có một SYCOPHANT chính hiệu, cô đăng gì cũng thả tim đầu tiên kèm ''bài giảng hay quá ạ'', thao túng tâm lý.', 'Kẻ nịnh hót', 'expert', 1490),
  ('v059', 'vitriolic', 'Đăng ảnh tự nấu cơm lên Threads, nhận ngay comment VITRIOLIC ''nhìn như đồ ăn cho mèo'', ủa alo.', 'Châm chọc, cay độc', 'expert', 1460),
  ('v060', 'abstruse', 'Tài liệu triết thầy gửi ABSTRUSE tới mức đọc xong một trang, mình cần thêm một trang để hiểu trang đó, xỉu ngang.', 'Thâm thúy, khó hiểu', 'expert', 1490),
  ('v061', 'anxious', 'Mẹ gọi đủ cả họ cả tên, chưa bắt máy mà đã ANXIOUS rà lại cả tuần mình làm gì, ét o ét.', 'Lo lắng, bồn chồn', 'beginner', 810),
  ('v062', 'blunt', 'Hỏi em gái bộ này mặc đi phỏng vấn được không, nó BLUNT luôn: ''nhìn như đi đám giỗ''.', 'Thẳng thắn đến mức thô lỗ', 'beginner', 820),
  ('v063', 'cautious', 'Đi buffet lần đầu nên CAUTIOUS lấy ít ít, no rồi mới phát hiện khu hải sản nằm ở bên kia, xu cà na.', 'Thận trọng, cẩn thận', 'beginner', 815),
  ('v064', 'demand', 'Bạn cùng phòng DEMAND mình tắt đèn lúc 11 giờ, trong khi nó cày phim tới 3 giờ sáng bằng loa ngoài, ủa alo.', 'Yêu cầu, đòi hỏi', 'beginner', 830),
  ('v065', 'efficient', 'Cách ôn thi EFFICIENT nhất của mình là đợi tới đêm cuối, áp lực tự bật não lên chế độ tua nhanh, keo lỳ.', 'Hiệu quả, năng suất', 'beginner', 840),
  ('v066', 'flexible', 'Lịch hẹn của nhóm bạn FLEXIBLE quá mức, hẹn 7 giờ thì 8 rưỡi đứa đầu tiên mới nhắn ''đang ra nè'', real.', 'Linh hoạt, dễ thích nghi', 'beginner', 835),
  ('v067', 'genuine', 'Lời khen GENUINE nhất tuần này là cô bán xôi nói ''dạo này con nhìn tươi ghê'', chữa lành hơn đi spa.', 'Thật thà, chân thành', 'beginner', 845),
  ('v068', 'hesitate', 'Săn sale 0 đồng thì mình không HESITATE nửa giây, còn trả lời tin nhắn crush thì soạn ba tiếng chưa gửi.', 'Do dự, ngập ngừng', 'beginner', 830),
  ('v069', 'impact', 'Một câu ''ăn gì cũng được'' có IMPACT tới cả buổi tối, đi bốn quán vẫn chưa ai được ăn, tới công chuyện.', 'Tác động, ảnh hưởng mạnh', 'beginner', 825),
  ('v070', 'justify', 'Mua đôi giày thứ tư trong tháng rồi tự JUSTIFY là đầu tư cho đôi chân, đúng chuẩn báo thủ ví tiền.', 'Biện minh, thanh minh', 'beginner', 850),
  ('v071', 'keen', 'Lớp trưởng KEEN tổ chức đi biển lắm, tạo group, làm bình chọn, riêng tin nhắn thu tiền là không ai rep, chằm zn.', 'Hăng hái, nhiệt tình', 'beginner', 835),
  ('v072', 'logical', 'Mượn tiền đi lẩu, hứa trả bằng tiền tiết kiệm được nhờ ăn lẩu ở nhà, nghe LOGICAL mà sai sai, thao túng tâm lý.', 'Hợp lý, theo logic', 'beginner', 840),
  ('v073', 'massive', 'Đặt online gấu bông ''size lớn'', hàng tới MASSIVE tới mức phòng trọ phải chọn giữ gấu hay giữ giường, u là trời.', 'Khổng lồ, to lớn', 'beginner', 820),
  ('v074', 'neglect', 'Cày rank cả tuần nên NEGLECT luôn chậu sen đá, nghe nói sen đá khó chết mà nó vẫn bỏ mình đi.', 'Bỏ bê, xao nhãng', 'beginner', 855),
  ('v075', 'obvious', 'Nó bảo ''tao với ổng chỉ là bạn'' mà ngày nào cũng ăn trưa chung, OBVIOUS tới mức cả lớp ăn cơm chó.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v076', 'persistent', 'Con mèo PERSISTENT thật, đóng cửa phòng là nó cào tới khi mở, mở rồi thì nó lại khum vào.', 'Kiên trì, dai dẳng', 'beginner', 860),
  ('v077', 'relevant', 'Hỏi bạn ''thi xong chưa'', nó gửi lại ba cái meme mèo khóc, chẳng RELEVANT gì mà hiểu kết quả luôn.', 'Liên quan, phù hợp', 'beginner', 845),
  ('v078', 'significant', 'Chuyển qua phòng trọ có máy lạnh là thay đổi SIGNIFICANT: ngủ ngon hẳn, còn hóa đơn điện thì tỉnh cả ngủ.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v079', 'tolerate', 'Mình TOLERATE được bạn cùng phòng ngáy, chứ vụ ăn mì xong để tô qua đêm là tới công chuyện.', 'Tha thứ, chịu đựng', 'beginner', 855),
  ('v080', 'utilize', 'Biết UTILIZE từng voucher freeship, mã giảm 10k với xu tích điểm, đơn 300 nghìn còn đúng 87 nghìn, slay.', 'Sử dụng, tận dụng', 'beginner', 860)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v081', 'valid', 'Đưa thẻ sinh viên hết hạn hai năm để xin giảm giá, chị thu ngân nhìn kỹ rồi nói ''hết VALID rồi em ơi''.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v082', 'willing', 'Nhắn group ''ai WILLING đi chợ mua đồ lẩu nè'', ba mươi người seen, đúng một đứa thả like.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v083', 'abstract', 'Hỏi crush thích kiểu người nào, nhận câu trả lời ABSTRACT ''ai có vibe dễ chịu'', nghe xong vẫn chưa biết nên sửa mình từ đâu.', 'Trừu tượng', 'beginner', 870),
  ('v084', 'benefit', 'BENEFIT lớn nhất ở công ty đầu tiên là máy lạnh mát, còn lương thì đủ mua cà phê để ngồi máy lạnh.', 'Lợi ích, phúc lợi', 'beginner', 825),
  ('v085', 'confident', 'Mặc đồ mới đi học CONFIDENT slay cả buổi sáng, trưa mới phát hiện còn nguyên cái tem giá sau lưng.', 'Tự tin', 'beginner', 835),
  ('v086', 'diverse', 'Tủ lạnh phòng trọ DIVERSE ghê: nửa hộp cơm, ba quả trứng, chai tương ớt và một miếng mặt nạ dưỡng da.', 'Đa dạng', 'beginner', 865),
  ('v087', 'evident', 'Sau đêm chạy deadline, quầng thâm EVIDENT tới mức đồng nghiệp hỏi có phải đang thử trend makeup khói.', 'Rõ ràng, hiển nhiên', 'beginner', 855),
  ('v088', 'focus', 'Định FOCUS học từ vựng hai tiếng, năm phút sau đã đứng trước tủ lạnh lần thứ ba dù không đói.', 'Tập trung', 'beginner', 820),
  ('v089', 'generate', 'Đăng một tấm ảnh đi biển lên story là GENERATE ra hai chục tin nhắn hóng biến ''đi với ai đó''.', 'Tạo ra', 'beginner', 845),
  ('v090', 'highlight', 'HIGHLIGHT đám cưới chị họ là màn bốc thăm, mình trúng nồi cơm điện kèm câu hỏi ''chừng nào tới con''.', 'Điểm nhấn, nổi bật', 'beginner', 830),
  ('v091', 'advocating', 'Cả phòng trọ đang ADVOCATING cho luật ai nấu thì người khác rửa chén, riêng đứa chỉ biết úp mì thì im re, chằm zn.', 'Ủng hộ, vận động cho', 'intermediate', 960),
  ('v092', 'ambivalent', 'Người yêu cũ nhắn lúc nửa đêm, cảm xúc AMBIVALENT dữ lắm: vừa muốn block, vừa lowkey muốn đọc lại ba lần.', 'Mâu thuẫn, vừa thích vừa ghét', 'intermediate', 980),
  ('v093', 'analogous', 'Ôn cả học kỳ trong một đêm ANALOGOUS với việc đổ nguyên bình nước vào cái ly, sáng ra nhớ được mỗi tên môn.', 'Tương tự, giống như', 'intermediate', 1050),
  ('v094', 'articulate', 'Trong đầu có nguyên bài TED talk, lên thuyết trình ARTICULATE được đúng câu ''dạ em xin hết'', toang.', 'Diễn đạt lưu loát', 'intermediate', 1000),
  ('v095', 'assertive', 'Tập cả tuần để ASSERTIVE với chủ trọ vụ tăng giá điện, gặp mặt cái tự nói ''dạ anh tính sao cũng được'', hết cứu.', 'Quyết đoán, tự tin khẳng định', 'intermediate', 970),
  ('v096', 'biased', 'Nhờ đứa bạn thân chấm outfit đi date là vô ích, nó BIASED quá, mặc bao tải nó cũng khen slay.', 'Thiên vị, có thành kiến', 'intermediate', 960),
  ('v097', 'bureaucratic', 'Xin cái giấy xác nhận sinh viên mà BUREAUCRATIC tới mức đi ba phòng, ký năm chữ, cuối cùng hẹn tuần sau, u là trời.', 'Quan liêu, nhiều thủ tục', 'intermediate', 1080),
  ('v098', 'catalyst', 'Bị crush seen không rep chính là CATALYST để mình đăng ký gym 6 giờ sáng, flex body là chuyện tháng sau.', 'Chất xúc tác, nhân tố kích thích', 'intermediate', 1020),
  ('v099', 'chronic', 'Bệnh đặt 7 cái báo thức rồi tắt cả 7 của mình là CHRONIC rồi, lên 8 cái cũng khum cứu nổi.', 'Mãn tính, kinh niên', 'intermediate', 975),
  ('v100', 'comprehensive', 'Group project kêu làm bản tóm tắt COMPREHENSIVE, nhóm trưởng gửi đúng ba gạch đầu dòng kèm chữ ''tự hiểu nha'', báo thủ.', 'Toàn diện, bao quát', 'intermediate', 990),
  ('v101', 'contentious', 'Trà sữa bao nhiêu phần trăm đường là chủ đề CONTENTIOUS nhất group chat, lỡ nói 100% là bị kick liền, real.', 'Gây tranh cãi', 'intermediate', 1060),
  ('v102', 'counterproductive', 'Thức tới 4 giờ sáng ôn thi rồi ngủ quên luôn giờ thi, đúng chuẩn COUNTERPRODUCTIVE, u là trời.', 'Phản tác dụng', 'intermediate', 1100),
  ('v103', 'credible', 'Shop online toàn feedback năm sao mà ảnh nào cũng cùng một bàn tay, nhìn khum CREDIBLE xíu nào.', 'Đáng tin', 'intermediate', 980),
  ('v104', 'cumulative', 'Mỗi ngày một ly trà sữa 35k nghe nhỏ xíu, nhưng con số CUMULATIVE tới cuối tháng là ví ét o ét.', 'Tích lũy, dồn lại', 'intermediate', 1040),
  ('v105', 'cynical', 'Sau ba lần bị bùng kèo, giờ group rủ đi Đà Lạt là mình CYNICAL liền: hết delulu rồi, chắc lại nói cho vui.', 'Hoài nghi, yếm thế', 'intermediate', 965),
  ('v106', 'decisive', 'Chọn món ở quán mất 15 phút mà đổi chuyên ngành thì DECISIVE ghê, nghĩ đúng một đêm là nộp đơn, ra đường tôi nể mỗi bạn.', 'Quyết đoán', 'intermediate', 970),
  ('v107', 'detrimental', 'Nằm lướt TikTok tư thế con tôm cả đêm cực kỳ DETRIMENTAL cho cái cổ, sáng dậy quay đầu như robot, tới công chuyện.', 'Có hại, bất lợi', 'intermediate', 1030),
  ('v108', 'dynamic', 'Đi làm năm nhất mới hiểu môi trường DYNAMIC nghĩa là sáng một yêu cầu, chiều đổi hai lần, tối hỏi sao chưa xong.', 'Năng động, thay đổi liên tục', 'intermediate', 955),
  ('v109', 'elaborate', 'Crush nhắn ''mình cần nói chuyện'', xin ELABORATE thêm thì nó bảo ''mai nói'', đêm đó ét o ét luôn.', 'Giải thích chi tiết', 'intermediate', 990),
  ('v110', 'empirical', 'Bằng chứng EMPIRICAL sau ba năm ở trọ: cứ mở nắp ly mì là chủ trọ gõ cửa thu tiền điện, xu cà na.', 'Dựa trên thực tế, thực nghiệm', 'intermediate', 1070),
  ('v111', 'explicit', 'Ủa alo, đã nói EXPLICIT là tao không ăn hành, nó vẫn gọi bánh mì full hành rồi bảo tưởng giỡn.', 'Rõ ràng, dứt khoát', 'intermediate', 1000),
  ('v112', 'formidable', 'Đối thủ FORMIDABLE nhất mùa săn sale không phải người khác, mà là cái app lag đúng lúc 0 giờ, hết cứu.', 'Đáng gờm', 'intermediate', 1050),
  ('v113', 'fragmented', 'Giấc ngủ ở trọ FRAGMENTED cỡ này: 1 giờ phòng bên hát karaoke, 3 giờ mèo đánh nhau, 5 giờ gà gáy, u là trời.', 'Phân mảnh, rời rạc', 'intermediate', 1020),
  ('v114', 'fundamental', 'Đi làm năm nhất mới thấy kỹ năng FUNDAMENTAL nhất là gật gù như hiểu trong cuộc họp, còn lại học sau, real.', 'Cơ bản, thiết yếu', 'intermediate', 960),
  ('v115', 'hypothetical', 'Câu hỏi HYPOTHETICAL thôi nha: nếu mày trúng Vietlott thì có trả tao 200k tháng trước khum?', 'Giả định, giả thuyết', 'intermediate', 1080),
  ('v116', 'implicit', 'Mẹ nhắn ''Tết này về dẫn ai về cũng được'', lời nhắc IMPLICIT nặng ký nhất năm, ok mom.', 'Ngầm định, ẩn ý', 'intermediate', 1040),
  ('v117', 'indispensable', 'Cục sạc dự phòng là món INDISPENSABLE khi đi concert, mất nó là mất luôn cơ hội đăng story flex.', 'Không thể thiếu', 'intermediate', 1090),
  ('v118', 'integrate', 'Bạn cùng phòng đòi INTEGRATE lịch tắm vào Google Calendar, ai trễ năm phút là bị tag lên group, ô dề thật.', 'Tích hợp', 'intermediate', 970),
  ('v119', 'intuitive', 'Máy giặt chung ở trọ có 14 nút mà chẳng nút nào INTUITIVE, cả xóm giặt đồ bằng niềm tin với manifest.', 'Trực quan, dễ hiểu', 'intermediate', 1010),
  ('v120', 'leverage', 'Biết bà chủ quán quý mình nên LEVERAGE triệt để, gọi ly 25k mà topping như ly 40k, nước đi keo lỳ.', 'Tận dụng lợi thế', 'intermediate', 1000)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v121', 'modicum', 'Ủa alo, chỉ xin một MODICUM tôn trọng thôi: ăn mì của tao thì ít ra chừa lại gói gia vị.', 'Một chút, lượng nhỏ tối thiểu', 'intermediate', 1030),
  ('v122', 'momentum', 'Đang có MOMENTUM dọn phòng ngon lành thì lục ra album ảnh cũ, ngồi chữa lành tới tối, phòng vẫn y nguyên.', 'Đà tiến, sức đẩy', 'intermediate', 990),
  ('v123', 'monotonous', 'Thực tập tháng đầu MONOTONOUS cỡ nào? Ngày nào cũng nhập Excel, tối mơ thấy mình là ô B12, chằm zn.', 'Đơn điệu, tẻ nhạt', 'intermediate', 975),
  ('v124', 'navigate', 'Lần đầu NAVIGATE chợ Bến Thành không có Google Maps, đi một vòng quay về đúng chỗ bán móc khóa, hết cứu.', 'Điều hướng, tìm cách vượt qua', 'intermediate', 960),
  ('v125', 'objective', 'Nói OBJECTIVE nha, ảnh thẻ của mày đâu có xấu, chỉ là nhìn như vừa thức ba đêm chạy deadline thôi.', 'Khách quan, mục tiêu', 'intermediate', 950),
  ('v126', 'overwhelming', 'Mở app ngân hàng sau 11.11 thấy sao kê dài ba trang, cảm giác OVERWHELMING tới mức xỉu ngang tại chỗ.', 'Choáng ngợp, quá tải', 'intermediate', 980),
  ('v127', 'paradox', 'PARADOX của tuổi 22: có thời gian thì không có tiền, có tiền thì bị deadline giữ chân, real.', 'Nghịch lý', 'intermediate', 1050),
  ('v128', 'perceive', 'Đứa bạn PERCEIVE dấu chấm trong tin ''ok.'' như lời tuyên chiến, nên giờ cả group nhắn tin khỏi chấm câu, ô dề.', 'Nhận thức, cảm nhận', 'intermediate', 1010),
  ('v129', 'perpetual', 'Sinh viên năm ba sống trong trạng thái PERPETUAL thiếu ngủ, ngủ trưa hai tiếng dậy vẫn hỏi nay thứ mấy.', 'Liên tục, vĩnh cửu', 'intermediate', 1060),
  ('v130', 'prevalent', 'Trend quay ''một ngày của tôi'' PREVALENT tới mức đứa bạn fomo quay luôn cảnh ngủ gục ở thư viện.', 'Phổ biến, thịnh hành', 'intermediate', 1020),
  ('v131', 'proactive', 'Đứa PROACTIVE nhất nhóm là đứa tạo file Drive đầu tiên, rồi biến mất tới ngày thuyết trình, báo thủ đúng nghĩa.', 'Chủ động', 'intermediate', 975),
  ('v132', 'profound', 'Chú xe ôm bảo ''xe hư thì sửa, tuổi trẻ thì không'', câu nói PROFOUND tới mức mình ngồi im lố nhà, chữa lành.', 'Sâu sắc, thâm thúy', 'intermediate', 1040),
  ('v133', 'rational', 'Mua áo khoác thứ năm vì đang giảm 50%, tự thao túng tâm lý bằng lý do nghe RATIONAL lắm, cho tới khi tủ đồ không đóng lại được.', 'Hợp lý, dựa trên lý trí', 'intermediate', 965),
  ('v134', 'skeptical', 'Tin tuyển dụng ghi ''việc nhẹ lương 20 triệu, không cần kinh nghiệm'', red flag to đùng, ai tỉnh cũng SKEPTICAL.', 'Hoài nghi, ngờ vực', 'intermediate', 990),
  ('v135', 'spontaneous', 'Chuyến đi Vũng Tàu SPONTANEOUS lúc 11 giờ đêm, sáng ra cả đám ngồi ngắm biển còn ví thì toang.', 'Ngẫu hứng, bột phát', 'intermediate', 1000),
  ('v136', 'subjective', 'Cái đẹp là SUBJECTIVE, nên tóc nhuộm tím của mày được cả họ bình luận đủ 7 kiểu dịp Tết, hết cứu.', 'Chủ quan', 'intermediate', 975),
  ('v137', 'sustainable', 'Ăn mì gói 30 ngày để mua vé concert nghe slay thật, nhưng chẳng SUSTAINABLE gì với cái bao tử của mày.', 'Bền vững', 'intermediate', 955),
  ('v138', 'transparent', 'Quỹ lớp cần TRANSPARENT hơn nha, thu 100k mỗi đứa mà cuối kỳ chỉ thấy một bịch hướng dương, check var gấp.', 'Minh bạch', 'intermediate', 970),
  ('v139', 'trivial', 'Cãi nhau 3 tiếng với người yêu vì chuyện TRIVIAL là ăn bún hay phở, cuối cùng đi ăn cơm tấm, rồi bắt cả group ăn cơm chó.', 'Tầm thường, vụn vặt', 'intermediate', 960),
  ('v140', 'unprecedented', 'Thằng keo kiệt nhất xóm trọ bỗng bao cả phòng trà sữa, sự kiện UNPRECEDENTED tới mức cả đám phải check var.', 'Chưa từng có tiền lệ', 'intermediate', 1070),
  ('v141', 'vulnerable', 'Ba giờ sáng nghe nhạc buồn là lúc mình VULNERABLE nhất, một cái story của người cũ cũng đủ khóc, chằm zn.', 'Dễ bị tổn thương', 'intermediate', 1010),
  ('v142', 'warranted', 'Nỗi lo của mẹ hoàn toàn WARRANTED: con nói đi Đà Lạt ''tiết kiệm'' mà story toàn quán cà phê view đồi, check var là lộ.', 'Có cơ sở, được cho phép', 'intermediate', 1080),
  ('v143', 'acrimonious', 'Vụ chia tiền lẩu trong group kết thúc cực ACRIMONIOUS chỉ vì một đĩa bò 120k, cả lớp kéo vào hóng biến.', 'Cay nghiệt, đầy ác ý', 'advanced', 1150),
  ('v144', 'admonish', 'Cô ADMONISH đứa bạn vì điểm danh hộ năm người, tính ra một mình nó gánh nửa lớp, keo lỳ thiệt.', 'Cảnh cáo, khiển trách nhẹ', 'advanced', 1200),
  ('v145', 'affluent', 'Nhìn đôi giày của thành viên mới là đoán gia đình AFFLUENT, check var xong cả đám im re.', 'Giàu có, thịnh vượng', 'advanced', 1120),
  ('v146', 'alleviate', 'Một ly bạc xỉu giúp ALLEVIATE nỗi đau thứ hai đầu tuần, ly thứ hai thì làm tim đập như vừa thi xong.', 'Giảm nhẹ, làm vơi bớt', 'advanced', 1140),
  ('v147', 'altruistic', 'Tưởng nó ALTRUISTIC nhường mình giường gần quạt, ai ngờ chỗ đó muỗi đông nhất phòng, thao túng tâm lý đỉnh.', 'Vị tha, không vụ lợi', 'advanced', 1180),
  ('v148', 'aberrant', 'Thằng bạn tự dậy 6 giờ sáng chạy bộ, hành vi ABERRANT tới mức cả phòng hỏi nó có đang thất tình khum.', 'Bất thường, lệch lạc', 'advanced', 1130),
  ('v149', 'anachronistic', 'Thầy bắt viết tay tiểu luận rồi scan thành PDF, quy định ANACHRONISTIC tới mức cả lớp phải đi mua bút lại.', 'Lỗi thời, sai thời điểm', 'advanced', 1280),
  ('v150', 'anecdotal', 'Vụ ''uống cà phê muối là qua môn'' chỉ là bằng chứng ANECDOTAL từ một anh khóa trên, vậy mà cả lớp xếp hàng.', 'Dựa trên lời kể, không chính thức', 'advanced', 1160),
  ('v151', 'anomaly', 'Một ANOMALY của xóm trọ: tuần này wifi mạnh bất thường, hóa ra cả xóm về quê hết, fomo dễ sợ.', 'Sự bất thường, dị thường', 'advanced', 1170),
  ('v152', 'antiquated', 'Cái laptop ANTIQUATED đời ông cố mở Word mất ba phút, đủ để úp mì và ăn xong, nồi cơm điện còn out trình nó.', 'Cổ lỗ sĩ, cũ kỹ', 'advanced', 1220),
  ('v153', 'apprehensive', 'Thấy mẹ nhắn ''tối nay gọi video nha con'', mình APPREHENSIVE liền, phòng trọ đang như bãi chiến trường, ét o ét.', 'E sợ, lo lắng về điều gì đó sắp xảy ra', 'advanced', 1150),
  ('v154', 'arduous', 'Hành trình ARDUOUS nhất năm: xách hai thùng mì với bao gạo lên tầng 5 không thang máy, tới nơi xỉu ngang.', 'Gian nan, cực nhọc', 'advanced', 1200),
  ('v155', 'austere', 'Tháng này sống AUSTERE thật: cơm trắng, trứng chiên, nước lọc, wifi thì xài ké quán cà phê.', 'Khắc khổ, giản dị quá mức', 'advanced', 1240),
  ('v156', 'banal', 'Caption ''cuộc sống là những chuyến đi'' nghe BANAL thật, nhưng ảnh Đà Lạt đẹp quá nên vẫn đăng, slay.', 'Tầm thường, vô vị, sáo rỗng', 'advanced', 1180),
  ('v157', 'benevolent', 'Chủ trọ BENEVOLENT đỉnh nóc kịch trần: Tết không tăng giá, còn tặng mỗi phòng một hộp mứt.', 'Nhân từ, rộng lượng', 'advanced', 1160),
  ('v158', 'callous', 'Chia tay qua tin nhắn đúng ngày sinh nhật, kèm câu ''chúc vui'', CALLOUS cỡ đó là red flag hạng nặng.', 'Vô tâm, nhẫn tâm', 'advanced', 1190),
  ('v159', 'capitulate', 'Thề không ăn sau 8 giờ tối, tới 11 giờ group rủ đi ăn ốc là CAPITULATE trong hai giây, gét gô.', 'Đầu hàng, chịu khuất phục', 'advanced', 1250),
  ('v160', 'circumvent', 'Thư viện cấm mang đồ ăn, nó CIRCUMVENT bằng cách giấu bánh mì trong hộp bút, thơm nguyên dãy bàn, ra đường tôi nể mỗi bạn.', 'Dùng mưu mẹo để lách luật', 'advanced', 1230)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v161', 'clandestine', 'Có một nhóm chat CLANDESTINE lowkey thiếu đúng một đứa, vì tuần sau là sinh nhật nó.', 'Bí mật, lén lút', 'advanced', 1270),
  ('v162', 'coerce', 'Bạn thân COERCE mình đi coi phim kinh dị bằng cách mua sẵn vé, giờ mình ngủ phải bật đèn, báo thủ.', 'Ép buộc, cưỡng bức', 'advanced', 1210),
  ('v163', 'complacent', 'Giữa kỳ được 9 điểm nên COMPLACENT, cuối kỳ lướt TikTok thay vì ôn, kết quả tới công chuyện.', 'Tự mãn, hài lòng với bản thân', 'advanced', 1170),
  ('v164', 'concede', 'Cãi cả buổi rồi cũng phải CONCEDE là mẹ nói đúng: áo trắng đừng giặt chung với quần jean, ok mom.', 'Thừa nhận (thường là miễn cưỡng)', 'advanced', 1150),
  ('v165', 'condescending', 'Anh khóa trên giảng bài bằng giọng CONDESCENDING, rồi tự giải sai đúng câu đầu tiên, ô dề thật sự.', 'Ra vẻ bề trên, khinh khỉnh', 'advanced', 1200),
  ('v166', 'convoluted', 'Cách tính điểm rèn luyện CONVOLUTED tới mức đứa học Toán ứng dụng cũng bó tay, hết cứu.', 'Phức tạp, rắc rối', 'advanced', 1220),
  ('v167', 'credulous', 'Đứa CREDULOUS nhất phòng tin lời shop ''mặc vào cao thêm 5 phân'', giờ áo dài tới gối, delulu thật sự.', 'Cả tin, dễ tin người', 'advanced', 1180),
  ('v168', 'curtail', 'Quyết tâm CURTAIL trà sữa còn hai ly một tuần, mới thứ hai đã xài hết suất vì fomo món mới.', 'Cắt bớt, rút ngắn', 'advanced', 1190),
  ('v169', 'cynicism', 'CYNICISM của mình với chữ ''sale sốc'' có lý do: ba lần mua xong tuần sau giá còn rẻ hơn, xu cà na.', 'Thái độ hoài nghi, yếm thế', 'advanced', 1160),
  ('v170', 'debilitating', 'Cơn buồn ngủ sau bữa trưa DEBILITATING cỡ nào? Ngồi họp mà lowkey gật gù như đang nghe nhạc chill.', 'Làm suy yếu, làm kiệt sức', 'advanced', 1240),
  ('v171', 'delineate', 'Trước khi ở ghép phải DELINEATE ai đổ rác, ai rửa chén, chứ không là tháng sau toang.', 'Vạch ra, mô tả chi tiết', 'advanced', 1260),
  ('v172', 'discrepancy', 'Ảnh menu thì tô bún đầy thịt, ra tới bàn còn ba lát, DISCREPANCY cỡ này là lừa tình, ủa alo.', 'Sự khác nhau, không thống nhất', 'advanced', 1200),
  ('v173', 'dismissive', 'Gửi idea vào group, nhóm trưởng đáp đúng chữ ''ừm'', DISMISSIVE vậy là red flag, tuần sau tự làm nha.', 'Gạt bỏ, coi thường', 'advanced', 1170),
  ('v174', 'disparate', 'Tủ đồ toàn món DISPARATE: áo hoa đi biển, quần tây đi làm, giày leo núi, ghép lại ra bộ đi đám cưới.', 'Khác hẳn nhau, tạp nham', 'advanced', 1210),
  ('v175', 'draconian', 'Luật phòng trọ DRACONIAN thật: sau 10 giờ khóa cổng, gọi cháy máy cũng chỉ nghe tiếng chó sủa, toang.', 'Hà khắc, khắc nghiệt', 'advanced', 1280),
  ('v176', 'duplicitous', 'Đứa bạn DUPLICITOUS nhất: trước mặt khen váy xinh, quay qua group khác chụp màn hình bàn tán, ra đường tôi nể mỗi bạn.', 'Hai mặt, gian trá', 'advanced', 1300),
  ('v177', 'elusive', 'Chiếc tất còn lại của đôi nào cũng ELUSIVE, giặt hai chiếc mà phơi lên chỉ còn một.', 'Khó nắm bắt, hay lảng tránh', 'advanced', 1190),
  ('v178', 'emulate', 'Manifest làm cô gái 5 giờ sáng, cố EMULATE routine mấy chị trên TikTok được hai ngày, ngày ba ngủ tới trưa.', 'Noi gương, học tập theo', 'advanced', 1160),
  ('v179', 'equivocate', 'Hỏi thẳng ''tối qua mày ăn hết bánh của tao hả'', nó EQUIVOCATE kiểu ''ai biết, chắc chuột'', thao túng tâm lý.', 'Nói mập mờ, lập lờ để lừa dối', 'advanced', 1290),
  ('v180', 'exorbitant', 'Ly cà phê ở phố đi bộ giá EXORBITANT, sinh viên ví mỏng như mình chỉ dám chụp hình cái menu, u là trời.', 'Quá mức, cắt cổ (về giá cả)', 'advanced', 1220),
  ('v181', 'expedient', 'Mì gói ba bữa liền là lựa chọn EXPEDIENT nhất mùa thi, còn cái dạ dày thì đang ét o ét gửi đơn khiếu nại.', 'Tiện lợi nhất thời, thực dụng', 'advanced', 1230),
  ('v182', 'extraneous', 'Hỏi crush tối nay đi xem phim không, nó gửi lại 12 tin EXTRANEOUS về con mèo nhà nó, câu hỏi chính thì lowkey bị bơ.', 'Không liên quan, ngoài lề', 'advanced', 1250),
  ('v183', 'fallacious', 'Lập luận ''sale 50% tức là mình lời 50%'' nghe FALLACIOUS rõ ràng, vậy mà tui vẫn bị nó thao túng tâm lý, chốt đơn liền.', 'Sai lầm, ngụy biện', 'advanced', 1270),
  ('v184', 'fastidious', 'Bạn cùng phòng trọ FASTIDIOUS tới mức xếp dép theo màu, tui để lệch một chiếc là tới công chuyện liền.', 'Khó tính, cầu kỳ thái quá', 'advanced', 1240),
  ('v185', 'fervent', 'Fan FERVENT cỡ nó canh vé concert từ 5 giờ sáng với ba cái báo thức, săn vé thì keo lỳ, bài tập nhóm thì chưa mở lần nào.', 'Nồng nhiệt, tha thiết', 'advanced', 1180),
  ('v186', 'flagrant', 'Nó chép nguyên bài essay của tui, đổi đúng cái tên rồi nộp, FLAGRANT tới mức thầy hỏi luôn hai đứa ai là bản gốc, u là trời.', 'Trắng trợn, lộ liễu', 'advanced', 1210),
  ('v187', 'fleeting', 'Động lực đi gym sau khi xem clip lột xác trên TikTok cực kỳ FLEETING, lướt hết clip là nằm luôn, hết cứu.', 'Thoáng qua, phù du', 'advanced', 1130),
  ('v188', 'forthright', 'Hỏi đứa FORTHRIGHT nhất nhóm outfit này ổn không, nó bảo ''giống rèm cửa nhà bà ngoại tao'', đau mà real.', 'Thẳng thắn, bộc trực', 'advanced', 1160),
  ('v189', 'frugal', 'Tuần cuối tháng sống FRUGAL đúng nghĩa: cơm trắng, trứng chiên và chai nước mắm mẹ gửi lên, cái ví đang ét o ét.', 'Tiết kiệm, thanh đạm', 'advanced', 1140),
  ('v190', 'futile', 'Giải thích cho mẹ vì sao 2 giờ sáng còn thức là nỗ lực FUTILE, kiểu gì cũng quy về cái điện thoại, hết cứu.', 'Vô ích, không kết quả', 'advanced', 1170),
  ('v191', 'gratuitous', 'Clip review quán cà phê có 30 giây nội dung với 3 phút cảnh rót nước quay chậm GRATUITOUS, ô dề gì đâu.', 'Vô lý, không cần thiết', 'advanced', 1260),
  ('v192', 'hegemony', 'Trong group chat lớp, HEGEMONY của phe gửi sticker con vịt là tuyệt đối, ai nhắn chữ tử tế là lạc loài.', 'Sự bá quyền, thống trị', 'advanced', 1300),
  ('v193', 'hubris', 'Tự tin không ôn vì ''môn này dễ mà'', HUBRIS cỡ đó nên vào phòng thi lật đề ra là toang.', 'Sự ngạo mạn quá mức', 'advanced', 1280),
  ('v194', 'hypocritical', 'Nó chửi người ta seen không rep là thiếu tôn trọng, trong khi đang ngâm 40 tin nhắn của tui, HYPOCRITICAL kiểu này đúng red flag.', 'Đạo đức giả', 'advanced', 1190),
  ('v195', 'idealistic', 'Kế hoạch dậy 5 giờ tập yoga, đọc sách, nấu bữa sáng healthy nghe IDEALISTIC quá, sáng ra tui ngủ tới 10 giờ, delulu thiệt.', 'Lý tưởng hóa, xa rời thực tế', 'advanced', 1150),
  ('v196', 'inadvertent', 'Cú thả tim INADVERTENT vào ảnh năm 2019 của crush lúc 1 giờ sáng, gỡ ra thì người ta nhận thông báo rồi, xu cà na.', 'Vô ý, không chủ tâm', 'advanced', 1230),
  ('v197', 'incongruent', 'Caption ghi ''đang chữa lành ở Đà Lạt'' mà ảnh là cảnh ngồi chạy deadline trong homestay, nhìn INCONGRUENT gì đâu.', 'Không phù hợp, mâu thuẫn', 'advanced', 1260),
  ('v198', 'indolent', 'Chủ nhật INDOLENT tới mức với cái remote cách nửa mét cũng phải cân nhắc năm phút xem có đáng không, lowkey hạnh phúc.', 'Lười biếng, nhác làm', 'advanced', 1200),
  ('v199', 'inexorable', 'Ngày đóng tiền trọ tới INEXORABLE như mặt trời mọc, dù tui đã manifest đủ kiểu cho nó lùi lại một tuần.', 'Không thể lay chuyển/ngăn cản', 'advanced', 1310),
  ('v200', 'insidious', 'Mỗi ngày một ly trà sữa nghe vô hại, cái INSIDIOUS là cuối tháng mở app ngân hàng mới thấy bay mất tiền nhà, xỉu ngang.', 'Âm thầm nguy hại', 'advanced', 1270)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v201', 'intransigent', 'Mẹ tui INTRANSIGENT vụ áo khoác, 35 độ vẫn bắt mang theo, cãi kiểu gì cũng ra câu ''lỡ trời trở gió'', thôi ok mom.', 'Cố chấp, không nhượng bộ', 'advanced', 1290),
  ('v202', 'irrevocable', 'Tin nhắn gửi nhầm vào group gia đình đã quá 24 tiếng, giờ nó IRREVOCABLE rồi, toang thật, chỉ còn cách đổi họ.', 'Không thể thu hồi/thay đổi', 'advanced', 1300),
  ('v203', 'lamentable', 'Tủ lạnh phòng trọ cuối tháng LAMENTABLE: một quả trứng, nửa chai tương ớt và hộp cơm vô chủ, u là trời.', 'Đáng buồn, đáng tiếc', 'advanced', 1220),
  ('v204', 'lethargic', 'Ăn trưa no xong vào tiết 1 giờ chiều, cả lớp LETHARGIC như bật chế độ tiết kiệm pin, cô hỏi gì cũng khum ai rep.', 'Uể oải, lờ đờ', 'advanced', 1180),
  ('v205', 'lucid', 'Đứa bạn đang ngái ngủ bỗng có một phút LUCID, dặn ''đừng nhắn cho người yêu cũ nha'' rồi ngáy tiếp, lời khuyên real nhất năm.', 'Sáng suốt, rõ ràng', 'advanced', 1140),
  ('v206', 'magnanimous', 'Thua kèo mà vẫn MAGNANIMOUS bao nguyên nhóm trà sữa, đúng là ra đường tôi nể mỗi bạn.', 'Hào hiệp, cao thượng', 'advanced', 1250),
  ('v207', 'malleable', 'Ý chí ăn kiêng của tui MALLEABLE như cục đất sét, đứa bạn rủ ăn ốc một câu là gét gô liền.', 'Dễ bị tác động, dễ uốn nắn', 'advanced', 1210),
  ('v208', 'mendacious', 'Bài đăng ''phòng rộng, sát trường'' MENDACIOUS hết cỡ, check var tới nơi thì phòng 9 mét, cách trường 7 cây số.', 'Sai sự thật, giả dối', 'advanced', 1320),
  ('v209', 'melancholy', 'Tối Chủ nhật nghe playlist nhạc buồn, tự nhiên MELANCHOLY nhớ cơm mẹ nấu, mở tủ lạnh chỉ có gói mì, cần chữa lành gấp.', 'U sầu, buồn bã', 'advanced', 1160),
  ('v210', 'mollify', 'Lỡ quên sinh nhật bạn thân, tui ship hộp bánh tráng trộn mới MOLLIFY được nó, vậy mà nó vẫn đòi thêm ly trà sữa, đàm phán keo lỳ thật.', 'Làm nguôi đi, xoa dịu', 'advanced', 1130),
  ('v211', 'mercurial', 'Thời tiết Sài Gòn MERCURIAL thật, sáng nắng cháy da, chiều mưa ầm ầm, tối lại mát rượi như chưa có gì, ủa alo.', 'Thất thường, hay thay đổi', 'advanced', 1110),
  ('v212', 'nefarious', 'Bạn cùng phòng NEFARIOUS: ăn vụng mì của tui rồi giấu vỏ dưới gầm giường, ai ngờ báo thủ bị mùi tôm chua tố cáo.', 'Hung ác, bất chính', 'advanced', 1310),
  ('v213', 'nonchalant', 'Cả nhóm hóng biến tới nóng máy, còn nhân vật chính thì NONCHALANT đăng story đi ăn lẩu như chưa có gì.', 'Thờ ơ, lãnh đạm', 'advanced', 1190),
  ('v214', 'nostalgic', 'Lục lại ảnh Facebook năm lớp 8 với mấy dòng status emo ô dề, vừa NOSTALGIC vừa muốn xóa sạch trước khi ai thấy.', 'Hoài niệm', 'advanced', 1130),
  ('v215', 'oblivious', 'Cả lớp biết nó thích bạn bàn trên, chỉ có bạn bàn trên là OBLIVIOUS, vẫn hồn nhiên nhờ nó chép bài giùm, hết cứu.', 'Vô tâm, không nhận thấy', 'advanced', 1160),
  ('v216', 'ominous', 'Mẹ nhắn đúng ba chữ ''về nói chuyện'' kèm dấu chấm, OMINOUS hơn mọi phim kinh dị tui từng xem, tới công chuyện rồi.', 'Điềm xấu, đáng lo ngại', 'advanced', 1180),
  ('v217', 'opaque', 'Cách app giao đồ ăn tính phí OPAQUE gì đâu, món 30 nghìn cộng phí dịch vụ, phí đóng gói, ra gần 70, ví lowkey khóc.', 'Mập mờ, không minh bạch', 'advanced', 1200),
  ('v218', 'ostentatious', 'Đi cà phê mà đặt chìa khóa xe với điện thoại mới ngay giữa bàn, kiểu flex OSTENTATIOUS cỡ đó ai cũng nhìn ra.', 'Phô trương, khoe mẽ', 'advanced', 1300),
  ('v219', 'pedantic', 'Rủ đi ăn mà đứa bạn PEDANTIC chỉ trả lời bằng cách sửa ''dzậy'' thành ''vậy'', đi hay không thì im re, u là trời.', 'Câu nệ, soi xét tiểu tiết', 'advanced', 1250),
  ('v220', 'perfidious', 'Hứa cùng nhau ế tới 30, vậy mà nó lặng lẽ có bồ rồi đăng ảnh, cú quay xe PERFIDIOUS nhất năm, cả group ăn cơm chó.', 'Phản bội, xảo trá', 'advanced', 1330),
  ('v221', 'pertinent', 'Họp nhóm hai tiếng toàn bàn trưa ăn gì, câu PERTINENT duy nhất là ''ủa alo, mai nộp bài rồi đó''.', 'Đúng trọng tâm, liên quan trực tiếp', 'advanced', 1150),
  ('v222', 'phlegmatic', 'Rớt môn, lỡ xe về quê, crush có bồ trong cùng một tuần mà nó vẫn PHLEGMATIC bảo ''đời mà'', chằm zn ăn bánh tráng tiếp.', 'Điềm tĩnh, lạnh lùng', 'advanced', 1280),
  ('v223', 'placid', 'Mặt hồ buổi sáng PLACID tới mức ngồi nhìn một lúc là quên luôn deadline, chữa lành được đúng năm phút thì điện thoại rung.', 'Điềm tĩnh, lặng lẽ', 'advanced', 1200),
  ('v224', 'polarizing', 'Món trà sữa sầu riêng POLARIZING cỡ này: nửa group xin công thức, nửa kia đòi rời nhóm, admin thì ngồi hóng biến.', 'Gây chia rẽ, phân cực', 'advanced', 1170),
  ('v225', 'pompous', 'Ông anh khóa trên họp lớp flex giọng POMPOUS về ''tư duy triệu đô'', hỏi ra thì vẫn xin tiền nhà đóng trọ.', 'Hợm hĩnh, vênh váo', 'advanced', 1220),
  ('v226', 'punctilious', 'Ra mắt nhà người yêu, bố bạn ấy PUNCTILIOUS từ cách rót trà tới cách cầm đũa, tui ngồi thẳng lưng mà trong lòng ét o ét.', 'Kỹ lưỡng, câu nệ nghi thức', 'advanced', 1280),
  ('v227', 'precarious', 'Chồng bát chưa rửa trong bồn đang ở thế PRECARIOUS, đứa nào trong phòng trọ đụng vào là tới công chuyện.', 'Bấp bênh, nguy hiểm', 'advanced', 1190),
  ('v228', 'presumptuous', 'Mới nói chuyện hai ngày đã tính tên con chung, PRESUMPTUOUS cỡ này thì delulu cũng phải gọi bằng sư phụ.', 'Tự phụ, quá trớn', 'advanced', 1260),
  ('v229', 'pretentious', 'Menu quán ghi ''nước lọc tinh khiết từ tầng sâu cảm xúc'' giá 45 nghìn, PRETENTIOUS tới mức tui gọi luôn để chụp, fomo mà.', 'Giả tạo, tự cao tự đại', 'advanced', 1230),
  ('v230', 'pugnacious', 'Con ngỗng nhà ngoại PUGNACIOUS dữ lắm, tui đi ngang sân thôi cũng bị rượt như nợ tiền nó, báo thủ của cả xóm.', 'Hay gây gổ, hiếu chiến', 'advanced', 1260),
  ('v231', 'abnegation', 'Nhường miếng gà rán cuối cho đứa bạn đang thất tình, mức ABNEGATION slay cỡ đó đáng ghi vào sử sách của nhóm.', 'Sự hy sinh, từ bỏ quyền lợi', 'expert', 1380),
  ('v232', 'abstemious', 'Đầu tuần thề sống ABSTEMIOUS, bỏ trà sữa bỏ đồ chiên, tối thứ Hai bạn rủ đi gà rán là gét gô liền.', 'Tiết chế, điều độ (ăn uống)', 'expert', 1420),
  ('v233', 'acerbic', 'Đăng ảnh tóc mới lên, bà chị họ comment ACERBIC ''cắt tiếc tiền ha'', 50 like trong 5 phút, out trình luôn bài gốc.', 'Chua cay, gay gắt', 'expert', 1390),
  ('v234', 'acumen', 'Đứa bạn có ACUMEN kinh doanh đỉnh nóc kịch trần, lấy sỉ bánh tráng về bán trong ký túc xá, một tuần đủ tiền đi Đà Lạt.', 'Sự nhạy bén, sắc sảo', 'expert', 1400),
  ('v235', 'adumbrate', 'Trưởng nhóm chỉ ADUMBRATE kế hoạch du lịch đúng một dòng ''đi biển'', còn ai đặt phòng ai lo xe thì tùy duyên, toang chắc.', 'Phác thảo, ám chỉ sơ lược', 'expert', 1470),
  ('v236', 'anachronism', 'Bố tui vẫn in bản đồ ra giấy trước mỗi chuyến đi, ANACHRONISM vậy mà đọc đường keo lỳ hơn cả Google Maps.', 'Sự lỗi thời, sai thời đại', 'expert', 1440),
  ('v237', 'anathema', 'Với dân ở trọ, tin nhắn ''tháng sau tăng giá điện'' là ANATHEMA, đọc xong xỉu ngang, chỉ muốn chặn số chủ nhà.', 'Điều cực kỳ ghét bỏ', 'expert', 1460),
  ('v238', 'apocryphal', 'Chuyện ''anh kia học tiếng Anh hai tuần nói như người bản xứ'' nghe APOCRYPHAL ghê, vậy mà cả lớp vẫn lưu lại để manifest.', 'Không xác thực, bị bịa đặt', 'expert', 1450),
  ('v239', 'apotheosis', 'Giật được deal 0 đồng đúng 0 giờ 0 phút là APOTHEOSIS của sự nghiệp săn sale, tui flex với cả group tới sáng.', 'Đỉnh cao, sự thần thánh hóa', 'expert', 1490),
  ('v240', 'approbation', 'Mặc áo mới về quê, cả họ check var từ đầu tới chân, phải có APPROBATION của bà nội thì mới thôi bàn tán.', 'Sự tán thành, chấp thuận', 'expert', 1430)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v241', 'arcane', 'Luật chơi board game đứa bạn mang tới ARCANE thật, đọc hướng dẫn 40 phút mà cả đám chưa ai biết đi lượt đầu, ủa alo.', 'Bí ẩn, kỳ bí, khó hiểu', 'expert', 1380),
  ('v242', 'arrant', 'Hứa làm slide rồi biến mất cả tuần, hôm thuyết trình hỏi ''mình làm phần nào ta'', đúng là báo thủ ARRANT.', 'Hoàn toàn, hết sức (nghĩa xấu)', 'expert', 1460),
  ('v243', 'artifice', 'Bài đăng ''pass lại vì không vừa size'' của shop thực ra là ARTIFICE để đẩy hàng tồn, tui bị thao túng tâm lý hai lần rồi.', 'Mưu mẹo, sự đánh tráo giả tạo', 'expert', 1420),
  ('v244', 'ascetic', 'Tuần thi cuối kỳ tui sống ASCETIC: xóa TikTok, ăn cơm hộp, ngủ bốn tiếng, fomo cỡ nào cũng không cài lại.', 'Khổ hạnh, tu hành', 'expert', 1440),
  ('v245', 'assiduous', 'Đứa bạn ASSIDUOUS nhất lớp ghi chép bằng năm màu bút, vở đẹp đỉnh nóc kịch trần, mùa thi cả lớp xếp hàng xin chụp.', 'Cần cù, siêng năng', 'expert', 1390),
  ('v246', 'atavistic', 'Nghe tiếng mở cửa lúc đang lén chơi game là bật dậy giả bộ học, phản xạ ATAVISTIC từ hồi lớp 5 vẫn còn nguyên.', 'Mang tính bản năng nguyên thủy', 'expert', 1480),
  ('v247', 'attenuate', 'Tai nghe chống ồn cũng chỉ ATTENUATE được phần nào tiếng karaoke nhà hàng xóm, phần còn lại thấm thẳng vào tim.', 'Làm yếu đi, giảm cường độ', 'expert', 1410),
  ('v248', 'august', 'Bước vào hội trường AUGUST của lễ tốt nghiệp, áo cử nhân thì đi thuê, dưới tà áo là đôi dép tổ ong, vẫn slay.', 'Uy nghi, đáng kính', 'expert', 1370),
  ('v249', 'avarice', 'Chủ trọ tăng tiền điện lên 4 nghìn một số, AVARICE lộ liễu tới mức cả dãy trọ lập group riêng để than, red flag to đùng.', 'Lòng tham tiền bạc', 'expert', 1430),
  ('v250', 'bellicose', 'Đói mà chưa được ăn trưa là tui thành BELLICOSE liền, ai hỏi ''ăn gì'' cũng muốn cãi tay đôi.', 'Hiếu chiến, thích gây hấn', 'expert', 1400),
  ('v251', 'byzantine', 'Thủ tục xin giấy xác nhận sinh viên BYZANTINE thật: ba phòng, bốn con dấu, hai tuần và một câu ''mai quay lại em'', ét o ét.', 'Rắc rối, cực kỳ phức tạp', 'expert', 1470),
  ('v252', 'capricious', 'Crush CAPRICIOUS tới mức hôm qua rep sau năm giây, hôm nay seen ba tiếng, tui check var lịch sử chat vẫn không ra quy luật.', 'Thất thường, hay thay đổi', 'expert', 1390),
  ('v253', 'castigate', 'Cô chủ nhiệm CASTIGATE cả lớp mười lăm phút vì vụ trốn tiết, xong mới phát hiện thủ phạm là lớp kế bên, ủa alo.', 'Chỉ trích dữ dội', 'expert', 1450),
  ('v254', 'caustic', 'Đứa em họ comment CAUSTIC dưới ảnh tui đi Đà Lạt: ''cảnh đẹp, tiếc là có người'', tới công chuyện với nó.', 'Cay nghiệt, châm chọc', 'expert', 1410),
  ('v255', 'chicanery', 'Shop xài đủ CHICANERY: giá gạch, mã giảm ''chỉ còn 2 phút'', đồng hồ đếm ngược reset mỗi lần vào lại, thao túng tâm lý dữ.', 'Mánh khóe, thủ thuật lừa dối', 'expert', 1480),
  ('v256', 'churlish', 'Bạn cùng phòng mượn sạc ba ngày chưa trả, nhắc thì đáp ''gì căng'' cực CHURLISH, tui lặng lẽ đổi mật khẩu wifi.', 'Thô lỗ, mất lịch sự', 'expert', 1380),
  ('v257', 'circumlocution', 'Hỏi ''có đi chơi khum'' mà nó trả lời cả đoạn CIRCUMLOCUTION về lịch học với thời tiết, dịch ra là khum.', 'Cách nói vòng vo, dài dòng', 'expert', 1490),
  ('v258', 'clairvoyant', 'Mẹ tui CLAIRVOYANT thật, chưa kịp kể đã biết tháng này cháy túi, gọi video câu đầu là ''gửi thêm hả con'', out trình thầy bói.', 'Sáng suốt, có khả năng tiên đoán', 'expert', 1420),
  ('v259', 'cloying', 'Cặp đôi phòng bên gọi nhau ''bé iu'' cả buổi tối, độ CLOYING cỡ này thì cả dãy trọ ăn cơm chó tới no.', 'Ngọt xớt, giả tạo đến phát ngấy', 'expert', 1360),
  ('v260', 'cogent', 'Tui soạn 10 slide lý lẽ COGENT xin bố mẹ cho đi Đà Lạt, bố xem hết rồi hỏi đúng một câu ''tiền ai trả'', toang.', 'Vững chắc, có sức thuyết phục', 'expert', 1380),
  ('v261', 'compunction', 'Nó ăn hết hộp bánh tui mua mà không có chút COMPUNCTION nào, còn trách tui mua ít, ra đường tôi nể mỗi bạn.', 'Sự hối hận, cắn rứt lương tâm', 'expert', 1430),
  ('v262', 'conflagration', 'Câu hỏi ''pizza có nên bỏ dứa không'' biến group lớp thành một CONFLAGRATION ba trăm tin nhắn, cả đám hóng biến tới khuya.', 'Đám cháy lớn, sự xung đột dữ dội', 'expert', 1460),
  ('v263', 'consternation', 'Cả phòng thi chìm trong CONSTERNATION khi đề ra đúng chương cô dặn ''phần này không cần học đâu'', xu cà na gì đâu.', 'Sự kinh hoàng, tiệt vọng', 'expert', 1460),
  ('v264', 'craven', 'Chó nhà hàng xóm sủa một tiếng là nó đẩy tui lên trước rồi chạy, màn CRAVEN nhất tui từng thấy, red flag tình bạn.', 'Hèn nhát', 'expert', 1400),
  ('v265', 'contrite', 'Đứa bạn làm đổ trà sữa lên laptop tui, mặt CONTRITE tới mức tui phải quay qua an ủi ngược lại nó.', 'Ăn năn, hối lỗi', 'expert', 1370),
  ('v266', 'convivial', 'Bữa lẩu ở trọ CONVIVIAL tới nỗi phòng bên sang xin nước mắm rồi ngồi lại luôn tới khuya, chữa lành thật sự.', 'Vui vẻ, thân thiện', 'expert', 1360),
  ('v267', 'copious', 'Bà ngoại gói đồ COPIOUS cho tui lên lại thành phố: ba bao gạo, hai can nước mắm và một con gà còn đang gáy, đỉnh nóc kịch trần.', 'Dồi dào, phong phú', 'expert', 1370),
  ('v268', 'cupidity', 'CUPIDITY trỗi dậy đúng lúc thấy livestream xả kho đồng giá 1 nghìn, canh tới 3 giờ sáng được đúng cái móc khóa, fomo mà.', 'Lòng tham (đặc biệt là tiền bạc)', 'expert', 1450),
  ('v269', 'dearth', 'Mùa thi ở thư viện là DEARTH ổ cắm trầm trọng, ai ngồi gần ổ điện là người quyền lực nhất tầng, real.', 'Sự khan hiếm, thiếu thốn', 'expert', 1390),
  ('v270', 'deference', 'Về quê ăn Tết, tui chào họ hàng với DEFERENCE tuyệt đối, cho tới khi nghe câu ''có bồ chưa'' là tới công chuyện.', 'Sự tôn trọng, cung kính', 'expert', 1400),
  ('v271', 'deleterious', 'Thức tới 3 giờ cày phim rồi sáng nốc ba ly cà phê, combo DELETERIOUS cho da mặt đỉnh nóc kịch trần luôn á.', 'Gây hại, có tác động xấu', 'expert', 1440),
  ('v272', 'denouement', 'Drama group lớp cãi nhau ba ngày ba đêm, DENOUEMENT là cả đám rủ nhau đi ăn lẩu như chưa có gì, hóng biến uổng công.', 'Kết cục, hạ màn', 'expert', 1460),
  ('v273', 'desultory', 'Ôn tiếng Anh kiểu DESULTORY, hôm nay Writing, mai lướt TikTok tips, tuần sau quên luôn mình đang học tới đâu, hết cứu.', 'Rời rạc, thiếu hệ thống', 'expert', 1470),
  ('v274', 'inveterate', 'Nó là đứa INVETERATE trễ hẹn, hẹn 7 giờ thì đúng 7 giờ mới bắt đầu đi tắm, red flag mà cả group quen luôn rồi.', 'Thâm căn cố đế, khó bỏ', 'expert', 1410),
  ('v275', 'lachrymose', 'Bộ phim Hàn này LACHRYMOSE dữ thần, mới tập hai mà hộp khăn giấy của cả phòng trọ đã toang.', 'Hay khóc, ủy mị, gây xúc động mạnh', 'expert', 1450),
  ('v276', 'lambaste', 'Quán trà sữa tăng giá mà ly còn nhỏ lại, dân Threads LAMBASTE suốt đêm, sáng ra quán lặng lẽ xóa bài, tới công chuyện.', 'Chỉ trích gay gắt', 'expert', 1420),
  ('v277', 'languid', 'Ăn xong cơm trưa văn phòng là cả team LANGUID như cá phơi khô, sếp hỏi gì cũng gật, lowkey đang ngủ gục.', 'Uể oải, lờ đờ', 'expert', 1380),
  ('v278', 'loquacious', 'Bác tài Grab LOQUACIOUS cỡ nào mà đi có mười lăm phút, mình đã thuộc hết lịch sử tình trường của bác, out trình podcast.', 'Nói nhiều, huyên thuyên', 'expert', 1390),
  ('v279', 'machiavellian', 'Nó khen mình nấu ăn ngon đúng hôm tới lượt nó rửa chén, nước cờ MACHIAVELLIAN thao túng tâm lý này mình nhận ra quá trễ.', 'Xảo quyệt, mưu mô chính trị', 'expert', 1490),
  ('v280', 'magniloquent', 'Bio Tinder ghi "kiến tạo tương lai" nghe MAGNILOQUENT vậy chứ hỏi ra là đang bán sim số đẹp, ô dề ghê.', 'Nói khoác lác, khoa trương', 'expert', 1480)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v281', 'maladroit', 'Định thả thính crush bằng một câu thơ, gõ sai chính tả ngay chữ "yêu", màn MALADROIT nhất học kỳ, u là trời.', 'Vụng về, thiếu khéo léo', 'expert', 1420),
  ('v282', 'malaise', 'Tối chủ nhật nào cũng lowkey có một cái MALAISE khó tả, chưa ai nhắc mà cơ thể đã biết mai là thứ hai.', 'Sự khó chịu, bất an mơ hồ', 'expert', 1400),
  ('v283', 'meretricious', 'Quán cà phê decor MERETRICIOUS hết cỡ, chụp ảnh slay thật nhưng ly bạc xỉu uống y nước đường.', 'Hào nhoáng nhưng vô giá trị', 'expert', 1470),
  ('v284', 'mettlesome', 'Đứa bạn METTLESOME dám tỏ tình crush ngay giữa tiệc sinh nhật đông người, cả bàn nín thở, ra đường tôi nể mỗi bạn.', 'Dũng cảm, đầy nghị lực', 'expert', 1440),
  ('v285', 'misanthropic', 'Sau ba tháng ở trọ chung năm người, mình thành MISANTHROPIC lúc nào không hay, giờ chỉ chữa lành bằng cách nói chuyện với con mèo.', 'Ghét người, lánh đời', 'expert', 1460),
  ('v286', 'mnemonic', 'Cô dạy cái MNEMONIC để nhớ thứ tự các hành tinh, giờ mình nhớ y câu thần chú mà quên mất nó dùng để làm gì, hết cứu.', 'Thuật ghi nhớ', 'expert', 1380),
  ('v287', 'mordant', 'Thằng bạn comment MORDANT dưới ảnh mới của mình: "Filter xịn đó, gửi tên app đi". Kém miếng khó chịu.', 'Châm chọc, cay nghiệt', 'expert', 1430),
  ('v288', 'munificent', 'Bà ngoại MUNIFICENT đỉnh nóc kịch trần, về quê ba ngày mà được dúi tiền, gà, gạo, cả bao xoài mang lên trọ.', 'Hào phóng, cực kỳ rộng rãi', 'expert', 1410),
  ('v289', 'nebulous', 'Hỏi "mình là gì của nhau", người ta đáp "thì cứ vậy đi", câu trả lời NEBULOUS cỡ này là red flag rồi.', 'Mơ hồ, mù mờ', 'expert', 1390),
  ('v290', 'noisome', 'Mở tủ lạnh phòng trọ sau kỳ nghỉ Tết, mùi NOISOME xộc ra làm cả dãy trọ ét o ét.', 'Hôi thối, khó chịu kinh khủng', 'expert', 1420),
  ('v291', 'obdurate', 'Ba mình OBDURATE lắm, nói mạng chậm là do trời mưa, check var cỡ nào cũng không chịu thay cái router đời 2015.', 'Cứng đầu, ngoan cố', 'expert', 1440),
  ('v292', 'obstreperous', 'Nhóm bàn bên OBSTREPEROUS từ đầu tới cuối, hát karaoke ngay trong quán cà phê học bài, nhắc ba lần vẫn hát, đúng báo thủ.', 'Ồn ào bướng bỉnh, khó kiểm soát', 'expert', 1470),
  ('v293', 'obtuse', 'Crush thả tim mọi story của mình mà mình tưởng người ta lỡ tay, nhìn lại mới thấy bản thân OBTUSE cỡ nào, u là trời.', 'Chậm hiểu, đần độn', 'expert', 1380),
  ('v294', 'officious', 'Cô chủ trọ OFFICIOUS tới mức biết mình chia tay trước cả mình, còn ghé hỏi "có cần cô giới thiệu đứa khác khum".', 'Hay lanh chanh, thích can thiệp chuyện người khác', 'expert', 1410),
  ('v295', 'oleaginous', 'Tin nhắn OLEAGINOUS kiểu "dạo này em xinh lên á" từ đứa bạn cũ, đọc tới dòng ba là thấy link đa cấp, ủa alo.', 'Nịnh bợ, bóng bẩy (nghĩa bóng)', 'expert', 1490),
  ('v296', 'onerous', 'Làm thủ tục nhập học online mà cần mười loại giấy tờ công chứng, nhiệm vụ ONEROUS hơn cả đề thi đại học, xỉu ngang.', 'Nặng nề, khó nhọc', 'expert', 1370),
  ('v297', 'opprobrium', 'Lỡ spoil cái kết phim trong group chat, mình hứng OPPROBRIUM cả tuần, bị loại khỏi kèo xem phần hai, báo thủ thì chịu.', 'Sự chỉ trích dữ dội, vết nhục', 'expert', 1460),
  ('v298', 'parsimonious', 'Rủ đi ăn mà nó PARSIMONIOUS tới mức chia bill tới từng 500 đồng tiền trà đá, keo lỳ có hạng.', 'Bủn xỉn, cực kỳ keo kiệt', 'expert', 1430),
  ('v299', 'pejorative', 'Mẹ gọi mình là "con nghiện điện thoại" bằng giọng PEJORATIVE, mình đáp "ok mom" trong lúc mẹ đang lướt TikTok.', 'Mang nghĩa xấu, có tính miệt thị', 'expert', 1420),
  ('v300', 'penurious', 'Cuối tháng PENURIOUS tới mức nhìn gói mì tôm như món sang trọng, phải chia ra ăn hai bữa, ví toang thật.', 'Nghèo túng, thiếu thốn tột cùng', 'expert', 1450),
  ('v301', 'perspective', 'Thử đổi PERSPECTIVE coi: crush không rep chưa chắc là ghét mình, có khi người ta chỉ... không quan tâm thôi, bớt delulu.', 'Góc nhìn, quan điểm', 'intermediate', 920),
  ('v302', 'ambitious', 'Plan hè của mình AMBITIOUS lắm, manifest đủ thứ: học code, tập gym, đọc mười cuốn sách; thực tế cày xong ba bộ phim.', 'Tham vọng', 'beginner', 850),
  ('v303', 'collaborate', 'Làm bài nhóm mà COLLABORATE kiểu một người làm, bốn người thả tim vào file Drive, ủa alo.', 'Hợp tác, cộng tác', 'beginner', 880),
  ('v304', 'adaptable', 'Ở trọ ba năm mình ADAPTABLE dữ lắm, mất điện thì học bằng đèn điện thoại, cúp nước thì ra tiệm gội đầu, keo lỳ chưa.', 'Dễ thích nghi', 'intermediate', 940),
  ('v305', 'consistent', 'Mình CONSISTENT đúng một thứ: tối nào cũng hứa sáng mai dậy sớm chạy bộ, hứa thì keo lỳ, dậy thì chưa.', 'Nhất quán, kiên trì', 'intermediate', 910),
  ('v306', 'obtain', 'Canh 0 giờ ba đêm liền mới OBTAIN được vé concert, giờ mới nhớ ra là chưa xin nghỉ phép, tới công chuyện.', 'Đạt được, giành được', 'intermediate', 960),
  ('v307', 'specific', 'Hỏi ăn gì thì nói SPECIFIC giùm cái, "gì cũng được" xong mình đề xuất món nào cũng bị chê, ủa alo.', 'Cụ thể, rõ ràng', 'beginner', 830),
  ('v308', 'valuable', 'Kho sticker meme trong máy là tài sản VALUABLE nhất mình có, đổi điện thoại là backup đầu tiên, lowkey quý hơn ảnh gia đình.', 'Quý giá, có giá trị', 'beginner', 840),
  ('v309', 'estimate', 'Mình ESTIMATE làm slide mất một tiếng, cuối cùng mất bốn tiếng vì ngồi chọn font, ô dề thật.', 'Ước tính', 'beginner', 880),
  ('v310', 'typical', 'Tủ quần áo đầy ứ mà vẫn thấy chẳng có gì mặc, tình trạng TYPICAL của mọi buổi sáng đi học, ô dề chứ đâu.', 'Điển hình, đặc trưng', 'beginner', 820),
  ('v311', 'versatile', 'Cái hoodie đen VERSATILE nhất tủ, đi học, đi cà phê, đi phỏng vấn cũng khoác được, slay mọi hoàn cảnh.', 'Linh hoạt, đa năng', 'intermediate', 1050),
  ('v312', 'sufficient', 'Lương thực tập SUFFICIENT để trả tiền trọ, còn tiền ăn thì tùy vào lòng tốt của mẹ ở quê.', 'Đầy đủ, đủ dùng', 'intermediate', 940),
  ('v313', 'priority', 'Trước kỳ thi, PRIORITY số một là ôn bài, vậy mà mình lại dọn phòng sạch nhất từ đầu năm tới giờ, hết cứu.', 'Sự ưu tiên', 'beginner', 850),
  ('v314', 'approach', 'APPROACH của nó với crush là like hết ảnh từ năm 2019 trong một đêm, crush xỉu ngang rồi block luôn.', 'Cách tiếp cận, phương pháp', 'intermediate', 920),
  ('v315', 'convince', 'Mất nguyên buổi tối để CONVINCE mẹ cho đi Đà Lạt với hội bạn, mẹ gật với điều kiện gọi video mỗi hai tiếng, ok mom.', 'Thuyết phục', 'beginner', 870),
  ('v316', 'procedure', 'PROCEDURE xin nghỉ ốm ở công ty mới cần ba chữ ký, tới khi xin xong thì mình khỏi bệnh luôn, u là trời.', 'Quy trình, thủ tục', 'intermediate', 950),
  ('v317', 'significance', 'Mất điện thoại rồi mới hiểu SIGNIFICANCE của việc nhớ số mẹ, vì trong đầu chỉ còn số của shipper, xu cà na.', 'Tầm quan trọng, ý nghĩa', 'intermediate', 1020),
  ('v318', 'reveal', 'Đứa bạn REVEAL người yêu mới trên story, cả group chat hóng biến rồi nhận ra là anh bán bánh mì đầu hẻm.', 'Tiết lộ, hé lộ', 'beginner', 830),
  ('v319', 'challenging', 'Môn Kinh tế lượng CHALLENGING tới mức cả lớp lập group chat riêng chỉ để than, khum ai hỏi bài.', 'Đầy thách thức', 'beginner', 890),
  ('v320', 'acquire', 'Sau một năm ở trọ, mình ACQUIRED kỹ năng nấu ba món chỉ bằng nồi cơm điện, slay nhẹ.', 'Có được, thu nhận được', 'intermediate', 960)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v321', 'beneficial', 'Ngủ trưa hai mươi phút cực BENEFICIAL cho não, ngủ hai tiếng thì dậy khum biết mình là ai.', 'Có lợi', 'beginner', 850),
  ('v322', 'capable', 'Mình hoàn toàn CAPABLE dậy lúc 5 giờ sáng, chỉ cần có một chuyến bay giá rẻ đang chờ là gét gô liền.', 'Có khả năng, năng lực', 'beginner', 870),
  ('v323', 'contradict', 'Story ghi "đang ôn thi chăm chỉ" mà giờ đó online Liên Quân, CONTRADICT nhau vậy check var là lộ liền.', 'Mâu thuẫn, trái ngược', 'intermediate', 980),
  ('v324', 'distinct', 'Hai ly trà sữa giá chênh 30 nghìn mà vị chẳng có gì DISTINCT, mình bị thao túng tâm lý trả thêm cho cái logo thôi.', 'Khác biệt rõ ràng', 'intermediate', 910),
  ('v325', 'eliminate', 'Quyết ELIMINATE trà sữa khỏi chế độ ăn, tuần sau mình ghiền luôn sinh tố bơ thêm kem, toang.', 'Loại bỏ, triệt tiêu', 'intermediate', 930),
  ('v326', 'generalize', 'Gặp một người yêu cũ tệ rồi GENERALIZE cả thế giới đều red flag là hơi quá rồi đó bà.', 'Khái quát hóa, đánh đồng', 'intermediate', 950),
  ('v327', 'hinder', 'Group chat gia đình nổ 99 tin nhắn về đám giỗ, HINDER công cuộc chạy deadline của mình trầm trọng, ét o ét.', 'Cản trở, kìm hãm', 'intermediate', 970),
  ('v328', 'implement', 'Kế hoạch tiết kiệm nghe hay lắm, tới lúc IMPLEMENT thì đụng ngay đợt sale 10.10, fomo thắng.', 'Triển khai, thực hiện', 'intermediate', 920),
  ('v329', 'inadequate', 'Ba tiếng ôn cho môn học cả kỳ là INADEQUATE thấy rõ, nhưng mình vẫn manifest được điểm A.', 'Thiếu hụt, không thỏa đáng', 'intermediate', 990),
  ('v330', 'maintain', 'MAINTAIN chuỗi Duolingo 300 ngày là thành tựu lớn nhất đời mình để flex, dù tiếng Pháp vẫn chỉ biết "bonjour".', 'Duy trì, bảo trì', 'beginner', 860),
  ('v331', 'notable', 'Thay đổi NOTABLE nhất sau năm đầu đi làm: mình đọc giá trước, chằm zn tính nhẩm rồi mới đọc tên món.', 'Đáng chú ý, nổi bật', 'beginner', 890),
  ('v332', 'optimistic', 'Còn đúng một tuần mà mình vẫn OPTIMISTIC lắm, tin rằng đọc slide hai đêm là qua môn, delulu nhẹ thôi.', 'Lạc quan', 'beginner', 840),
  ('v333', 'partial', 'Mẹ PARTIAL rõ ràng, em trai làm vỡ chén thì "không sao con", mình làm vỡ thì nghe giảng tới tối, kém miếng khó chịu ghê.', 'Một phần, thiên vị', 'beginner', 830),
  ('v334', 'practical', 'Món quà sinh nhật PRACTICAL nhất mình từng nhận là một thùng mì, tới đúng tuần cuối tháng, keo lỳ.', 'Thực tế, thực tiễn', 'beginner', 870),
  ('v335', 'quickly', 'Nghe tiếng xe mẹ đầu ngõ, mình QUICKLY tắt game, mở sách, bày đủ bút highlight, diễn out trình luôn.', 'Nhanh chóng', 'beginner', 800),
  ('v336', 'reaction', 'REACTION của mẹ khi thấy mình nhuộm tóc hồng: im lặng ba giây rồi hỏi đúng một câu "bao nhiêu tiền", tới công chuyện.', 'Phản ứng', 'beginner', 820),
  ('v337', 'skepticism', 'Xem review "quán ngon nhất Sài Gòn" trên TikTok với đầy SKEPTICISM, vì clip nào cũng kèm mã giảm giá, phải check var.', 'Sự hoài nghi', 'intermediate', 1040),
  ('v338', 'tendency', 'Mình có TENDENCY mở tủ lạnh mỗi lần bí bài, đề chưa giải xong mà tủ lạnh đã ét o ét.', 'Xu hướng, khuynh hướng', 'intermediate', 910),
  ('v339', 'unexpected', 'Tin nhắn UNEXPECTED nhất năm nay: người yêu cũ hỏi mượn tài khoản Netflix, cả group hóng biến.', 'Bất ngờ, không mong đợi', 'beginner', 850),
  ('v340', 'validate', 'Gửi outfit vào group nhờ VALIDATE, cả đám khen đẹp, ra đường mới thấy ba người mặc y chang, xu cà na.', 'Xác nhận, phê chuẩn', 'intermediate', 940),
  ('v341', 'worthwhile', 'Xếp hàng hai tiếng vì fomo ổ bánh mì nổi trên TikTok, miếng đầu thấy WORTHWHILE, tới miếng hai thì hết chắc.', 'Đáng công, xứng đáng', 'intermediate', 900),
  ('v342', 'yield', 'Ba tháng nhắn chào buổi sáng cuối cùng cũng YIELD kết quả: crush rủ mình vô nhóm làm bài tập, delulu tưởng hẹn hò.', 'Mang lại, sản sinh ra, nhượng bộ', 'intermediate', 1020),
  ('v343', 'abandon', 'Mua bộ màu nước về để chữa lành, vẽ đúng một bức rồi ABANDON nó trong góc tủ tới giờ.', 'Từ bỏ, bỏ rơi', 'beginner', 880),
  ('v344', 'brief', 'Ai BRIEF giùm mình drama group lớp với, mới ngủ trưa dậy mà đã 300 tin nhắn chưa đọc, fomo dữ.', 'Ngắn gọn, tóm tắt', 'beginner', 830),
  ('v345', 'certain', 'Mình CERTAIN là đã khóa cửa phòng trọ rồi, nhưng vẫn quay xe về check var lần thứ ba.', 'Chắc chắn', 'beginner', 810),
  ('v346', 'decline', 'Lịch sự DECLINE thiệp cưới của đứa bạn cấp hai mười năm không nói chuyện, cái ví thở phào, chữa lành.', 'Từ chối, suy giảm', 'intermediate', 940),
  ('v347', 'accommodate', 'Phòng trọ 12 mét vuông mà phải ACCOMMODATE cả hội bạn từ quê lên thi, ngủ xếp như cá mòi, real.', 'Đáp ứng, cung cấp chỗ ở', 'intermediate', 960),
  ('v348', 'deliberate', 'Seen tin nhắn rồi ba ngày sau mới rep là DELIBERATE chứ ai mà bận dữ vậy trời, red flag.', 'Cố ý, thận trọng', 'intermediate', 980),
  ('v349', 'financial', 'Tình hình FINANCIAL giữa tháng của mình: một trăm nghìn, hai gói mì và niềm tin vào ngày lãnh lương.', 'Thuộc về tài chính', 'beginner', 840),
  ('v350', 'generous', 'Nó GENEROUS bất ngờ, bao cả nhóm trà sữa, hóa ra là thao túng tâm lý để nhờ cả đám làm hộ phần thuyết trình.', 'Hào phóng, rộng lượng', 'beginner', 835),
  ('v351', 'immediate', 'Nhắn "đi ăn khum" là nó phản hồi IMMEDIATE, còn nhắc trả tiền nợ thì đọc ba ngày chưa rep.', 'Ngay lập tức', 'beginner', 845),
  ('v352', 'knowledgeable', 'Đứa bạn KNOWLEDGEABLE về mọi quán ốc trong thành phố, out trình food reviewer, nhưng hỏi bài Kinh tế vi mô thì ngơ ngác.', 'Am hiểu, có kiến thức rộng', 'intermediate', 950),
  ('v353', 'motivate', 'Thứ duy nhất MOTIVATE mình đi học sáng thứ hai là ổ bánh mì chảo trước cổng trường.', 'Thúc đẩy, tạo động lực', 'beginner', 860),
  ('v354', 'negative', 'Đọc comment NEGATIVE dưới clip đầu tay xong mình xóa app, tối lại cài lại để đọc tiếp, hết cứu.', 'Tiêu cực', 'beginner', 810),
  ('v355', 'quality', 'Áo sale 50 nghìn QUALITY đúng giá, giặt lần đầu là co lại thành áo của em mình, toang.', 'Chất lượng', 'beginner', 805),
  ('v356', 'reasonable', 'Giá phòng trọ nghe REASONABLE lắm, tới lúc chủ nhà báo tiền điện 4 nghìn một số là mình xỉu ngang.', 'Hợp lý, phải chăng', 'beginner', 855),
  ('v357', 'ultimate', 'Mục tiêu ULTIMATE của mùa thi: đậu hết, ngủ đủ, không học lại môn nào để còn về quê ăn Tết, manifest gấp.', 'Cuối cùng, tối thượng', 'intermediate', 940),
  ('v358', 'vague', '"Hôm nào cà phê nha" là lời hẹn VAGUE đỉnh nóc kịch trần, hai đứa nói câu này từ hồi tốt nghiệp tới giờ.', 'Mơ hồ, mập mờ', 'intermediate', 910),
  ('v359', 'dependable', 'Đứa bạn DEPENDABLE nhất group nhớ lịch thi giùm cả lớp, còn gửi đề cương lúc 12 giờ đêm, ra đường tôi nể mỗi bạn.', 'Đáng tin cậy', 'intermediate', 930),
  ('v360', 'effective', 'Cách học thuộc EFFECTIVE nhất của mình: hẹn đứa bạn dò bài, sai một câu là bao một ly trà sữa, gét gô.', 'Hiệu quả', 'beginner', 850)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v361', 'appropriate', 'Mặc đồ ngủ hình con gấu đi họp Zoom với khách hàng, mình thấy cũng APPROPRIATE, cho tới khi phải đứng dậy lấy sạc, u là trời.', 'Phù hợp, thích hợp', 'intermediate', 960),
  ('v362', 'behave', 'Về quê ăn giỗ, mẹ dặn phải BEHAVE cho đàng hoàng, vậy mà mới ngồi năm phút đã cãi tay đôi với ông chú về lương IT, toang.', 'Cư xử, ăn ở', 'beginner', 820),
  ('v363', 'coincidence', 'Vừa nói xấu đứa cùng phòng trọ trong group chat thì nó gõ cửa, mong đây chỉ là COINCIDENCE, ét o ét.', 'Sự trùng hợp ngẫu nhiên', 'intermediate', 980),
  ('v364', 'determined', 'Tối Chủ nhật DETERMINED từ mai dậy 5 giờ chạy bộ, manifest đủ kiểu, sáng thứ Hai tắt báo thức bằng một ngón tay mà mắt chưa kịp mở.', 'Quyết tâm, kiên quyết', 'beginner', 880),
  ('v365', 'encourage', 'Cả group ENCOURAGE tao nhắn tin cho crush trước, tới lúc bị seen không rep thì đứa nào cũng bận đi tắm, bạn bè red flag.', 'Khuyến khích, động viên', 'beginner', 860),
  ('v366', 'familiar', 'Mở đề thi ra thấy câu nào cũng FAMILIAR, kiểu đã gặp ở đâu rồi, chắc là trong giấc mơ đêm qua.', 'Quen thuộc', 'beginner', 810),
  ('v367', 'hinder', 'Wifi phòng trọ chập chờn đang HINDER sự nghiệp chạy deadline của tôi, mà lướt TikTok thì mượt re, thao túng tâm lý ghê.', 'Cản trở, kìm hãm', 'intermediate', 970),
  ('v368', 'imitate', 'Đứa bạn IMITATE giọng cô chủ nhiệm y chang, cả lớp đang nghiêng ngả thì phát hiện cô đứng ngay cửa sổ, tới công chuyện.', 'Bắt chước, nhại lại', 'intermediate', 940),
  ('v369', 'jealous', 'Thấy bạn thân đăng ảnh đi Đà Lạt với người yêu, tôi khum JEALOUS đâu, chỉ là lỡ tay xem story đó bảy lần.', 'Ghen tị, ghen tuông', 'beginner', 830),
  ('v370', 'limit', 'Thẻ tín dụng chạm LIMIT từ hôm săn sale 10.10, giờ quẹt mua ly trà sữa cũng nghe máy kêu từ chối, ét o ét.', 'Giới hạn, hạn mức', 'beginner', 815),
  ('v371', 'notice', 'Đi làm cả buổi sáng mới NOTICE là mình mang hai chiếc dép khác màu, mà không ai nói, đồng nghiệp lowkey ác.', 'Để ý thấy, nhận ra', 'beginner', 810),
  ('v372', 'patient', 'Chờ shipper giao đơn ba ngày tôi PATIENT lắm, nhưng chờ crush rep tin ba phút là đi vòng vòng khắp phòng, hết cứu.', 'Kiên nhẫn', 'beginner', 825),
  ('v373', 'quarrel', 'Hai đứa cùng phòng trọ QUARREL cả tối vì ai rửa chén, cuối cùng đặt đồ ăn ngoài cho khỏi có chén mà rửa, keo lỳ.', 'Cãi vã, tranh chấp', 'intermediate', 930),
  ('v374', 'stubborn', 'Con laptop cũ STUBBORN thật, bấm cập nhật là nó quay vòng tròn tới sáng, như đang thao túng tâm lý mình.', 'Bướng bỉnh, lỳ lợm', 'beginner', 860),
  ('v375', 'temporary', 'Nghỉ việc nói là TEMPORARY để chữa lành, giờ đã tháng thứ tư và tôi quên luôn mật khẩu email công ty.', 'Tạm thời', 'beginner', 870),
  ('v376', 'urgent', 'Mẹ nhắn "Gọi mẹ gấp, chuyện URGENT", tôi run tay bấm gọi, hóa ra mẹ hỏi cách gửi sticker trên Zalo, xỉu ngang.', 'Khẩn cấp', 'beginner', 845),
  ('v377', 'willing', 'Ai rủ đi lẩu nửa đêm tôi WILLING liền, gét gô trong một nốt nhạc; rủ chạy bộ 6 giờ sáng thì tôi xin phép mất sóng.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v378', 'accurate', 'App bói tình yêu bảo crush đang thích mình, ACCURATE hay không chưa biết, nhưng mình tin rồi, delulu một chút cho vui.', 'Chính xác', 'beginner', 880),
  ('v379', 'believable', 'Lý do trễ hẹn của nó là "kẹt xe trên cầu" nghe cũng BELIEVABLE, nếu story của nó khum đang ở quán ốc.', 'Có thể tin được', 'beginner', 815),
  ('v380', 'convenient', 'Ở trọ ngay dưới nhà là quán trà sữa, CONVENIENT cực, chỉ có cái ví là lowkey muốn dọn nhà đi chỗ khác.', 'Tiện lợi', 'beginner', 820),
  ('v381', 'dependable', 'Trong group du lịch luôn có một đứa DEPENDABLE giữ vé, giữ tiền, giữ luôn sạc dự phòng cho cả đám báo thủ.', 'Đáng tin cậy', 'intermediate', 930),
  ('v382', 'effective', 'Thử đủ app học tiếng Anh, cách EFFECTIVE nhất vẫn là con cú xanh nhắc bài kiểu đe dọa lúc nửa đêm, out trình mọi thầy cô.', 'Hiệu quả', 'beginner', 850),
  ('v383', 'grateful', 'Cuối tháng còn 50 nghìn, tôi GRATEFUL vô cùng vì mẹ gửi lên thùng mì với hũ chà bông, kèm câu "ăn uống cho đàng hoàng", ok mom.', 'Biết ơn', 'beginner', 860),
  ('v384', 'honest', 'Nhờ bạn thân cho ý kiến HONEST về ảnh đại diện mới, nó im lặng ba phút rồi hỏi "chụp lúc đang buồn ngủ hả", bạn real.', 'Thành thật, chân thật', 'beginner', 810),
  ('v385', 'ignore', 'Tôi IGNORE thông báo của group lớp suốt tuần, tới lúc vào hóng biến mới biết mai thi giữa kỳ.', 'Phớt lờ, lờ đi', 'beginner', 820),
  ('v386', 'intention', 'Nó thả tim mọi story của tôi lúc 2 giờ sáng, INTENTION là gì thì chưa rõ, cả group đang check var.', 'Ý định, mục đích', 'intermediate', 910),
  ('v387', 'manage', 'Lương thực tập 3 triệu, tôi MANAGE được tới ngày 12 rồi bắt đầu sống bằng niềm tin và trà đá.', 'Quản lý, xoay xở', 'beginner', 850),
  ('v388', 'necessary', 'Đi săn sale thì món nào cũng thấy NECESSARY, fomo dữ lắm, về mở hộp ra mới tự hỏi mua máy đánh trứng làm chi.', 'Cần thiết', 'beginner', 840),
  ('v389', 'optimistic', 'Thi trượt môn lần hai mà nó vẫn OPTIMISTIC, bảo học lại lần ba để thân với thầy hơn, hết cứu.', 'Lạc quan', 'beginner', 840),
  ('v390', 'partial', 'Thầy chỉ cho PARTIAL điểm câu cuối vì tôi viết đúng mỗi chữ "Giải", nhưng có còn hơn không.', 'Một phần, thiên vị', 'beginner', 830),
  ('v391', 'significant', 'Bỏ trà sữa một tháng, ví dư ra số tiền SIGNIFICANT tới mức tôi tự thưởng một ly trà sữa size lớn, ủa alo.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v392', 'tolerate', 'Tôi TOLERATE được bạn cùng phòng ngáy, nói mớ, nhưng ăn vụng gói snack cuối cùng của tôi là tới công chuyện.', 'Chịu đựng, tha thứ', 'beginner', 855),
  ('v393', 'utilize', 'Tôi UTILIZE hết mười mã giảm giá trong một đơn, tiết kiệm được 47 nghìn và mua thêm ba món không cần, đỉnh nóc kịch trần.', 'Sử dụng, tận dụng', 'beginner', 860),
  ('v394', 'valid', 'Lý do nghỉ học "bị cảm" chỉ VALID khi mày không đăng story check-in Vũng Tàu cùng ngày, báo thủ ghê.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v395', 'wonder', 'Nửa đêm nằm WONDER không biết hồi lớp 3 mình nói gì mà đứa bạn giận, giờ nó có con rồi mà tôi vẫn chằm zn.', 'Tự hỏi, băn khoăn', 'beginner', 810),
  ('v396', 'admit', 'Cãi nhau ba tiếng, nó cũng ADMIT là ăn hết hộp bánh của tôi, kèm lý do "tại nó nằm trong tủ lạnh dụ tao", ra đường tôi nể mỗi bạn.', 'Thừa nhận, nhận vào', 'beginner', 865),
  ('v397', 'boring', 'Buổi học online BORING tới mức tôi tắt cam đi nấu mì, quay lại thì cô đang gọi tên tôi lần thứ ba, tới công chuyện.', 'Buồn chán, tẻ nhạt', 'beginner', 800),
  ('v398', 'complain', 'Cả tuần COMPLAIN với group là hết tiền, cuối tuần vẫn có mặt đầy đủ ở buổi đi bar, real nể.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v399', 'doubt', 'Áo khoác "hàng hiệu" giá 99 nghìn, tôi có DOUBT nhẹ, nhưng khum đủ mạnh để ngón tay ngừng bấm đặt hàng.', 'Nghi ngờ', 'beginner', 855),
  ('v400', 'eager', 'Đầu năm nhất ai cũng EAGER đi học đủ buổi, tới giữa kỳ check var thì lớp còn đúng thầy và cái máy chiếu.', 'Háo hức, hăm hở', 'intermediate', 920)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v401', 'force', 'Mẹ FORCE tôi đi xem mắt con của bạn mẹ, ngồi mười phút thì hai đứa phát hiện cùng bị ép, hợp nhau ghê.', 'Ép buộc, lực lượng', 'beginner', 840),
  ('v402', 'gather', 'Lớp cấp 3 GATHER lại sau 5 năm, nửa bàn dắt theo người yêu, nửa còn lại ngồi ăn cơm chó tới no.', 'Tập hợp, thu thập', 'beginner', 830),
  ('v403', 'hardly', 'Từ hồi đi làm, tôi HARDLY gặp ánh mặt trời, sáng đi lúc trời chưa sáng, tối về lúc trời đã tối thui, u là trời.', 'Hầu như không', 'beginner', 815),
  ('v404', 'imagine', 'Nhắn crush xong, tôi đã IMAGINE luôn cảnh hai đứa nuôi con mèo tên Bơ, trong khi người ta còn chưa seen, delulu.', 'Tưởng tượng', 'beginner', 805),
  ('v405', 'kindness', 'Chị shipper đứng dưới mưa chờ tôi chạy xuống, KINDNESS này xứng đáng năm sao và một ly cà phê sữa, chữa lành ghê.', 'Sự tử tế, lòng tốt', 'beginner', 820),
  ('v406', 'loose', 'Quần mua online size S mà mặc vào LOOSE như quần của ông nội, hình một đằng hàng một nẻo, xỉu ngang.', 'Lỏng lẻo, rộng', 'beginner', 835),
  ('v407', 'mention', 'Lỡ MENTION tên người yêu cũ của bạn thân trong buổi cà phê, nguyên bàn im lặng như đang chờ đọc điểm thi, đúng báo thủ.', 'Đề cập đến', 'beginner', 840),
  ('v408', 'offer', 'Công ty mới OFFER mức lương gấp rưỡi, tôi đồng ý trong hai giây rồi giả vờ suy nghĩ thêm hai ngày.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v409', 'particular', 'Hỏi muốn ăn gì thì nó bảo không có món nào PARTICULAR, gợi ý thì món nào cũng "thôi, món khác đi", ủa alo.', 'Cụ thể, đặc biệt', 'intermediate', 910),
  ('v410', 'qualify', 'Học bổng yêu cầu điểm 8.0 mới QUALIFY, tôi được 7.98, đúng là kém miếng khó chịu.', 'Đủ điều kiện, tư cách', 'intermediate', 940),
  ('v411', 'struggle', 'Mỗi lần mở file Excel của sếp là tôi STRUGGLE cả buổi, công thức nào cũng lồng nhau như phim trinh thám, xỉu ngang.', 'Vật lộn, đấu tranh', 'beginner', 880),
  ('v412', 'thorough', 'Trả phòng trọ, bà chủ kiểm tra THOROUGH tới mức soi từng lỗ đinh trên tường để trừ cọc, xu cà na thiệt.', 'Kỹ lưỡng, thấu đáo', 'intermediate', 960),
  ('v413', 'unique', 'Tự tin mặc chiếc áo UNIQUE săn ở shop đồ si, tới công ty gặp ngay chị kế toán mặc y chang, u là trời.', 'Độc nhất, độc đáo', 'beginner', 860),
  ('v414', 'whisper', 'Đứa ngồi kế WHISPER đáp án trong giờ kiểm tra, tôi chép theo đầy tin tưởng và hai đứa cùng sai, toang.', 'Thì thầm', 'beginner', 830),
  ('v415', 'annoying', 'Không gì ANNOYING bằng đứa gửi tin nhắn thoại 5 phút chỉ để hỏi "mày rảnh không", red flag.', 'Làm phiền, khó chịu', 'beginner', 820),
  ('v416', 'believe', 'Nó khoe tự nấu nồi lẩu Thái, tôi đã định BELIEVE, cho tới khi check var thấy cái hộp có logo quán trong góc ảnh.', 'Tin tưởng', 'beginner', 800),
  ('v417', 'critical', 'Pin điện thoại còn 2% đúng lúc đang chốt hẹn với crush, giai đoạn CRITICAL nhất đời tôi, ét o ét.', 'Quan trọng, nguy cấp, phê bình', 'intermediate', 970),
  ('v418', 'delighted', 'Bà ngoại DELIGHTED ra mặt khi tôi về quê, rồi quay qua hỏi "sao ốm vậy con" dù tôi vừa lên 3 ký.', 'Vui mừng, hài lòng', 'beginner', 890),
  ('v419', 'frustrated', 'Code chạy ngon trên máy tôi, lên máy trưởng nhóm thì lỗi đỏ màn hình, FRUSTRATED tới mức muốn đi bán trà chanh, toang.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v420', 'influence', 'Một video review 30 giây có INFLUENCE ghê thật, fomo cái là tôi chốt máy làm bánh waffle, dùng đúng một lần.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v421', 'judge', 'Đồng nghiệp mới nhìn khó gần, tôi lỡ JUDGE là red flag, ai ngờ ổng là người duy nhất mang bánh chia cả phòng.', 'Đánh giá, phán xét', 'beginner', 830),
  ('v422', 'knowledge', 'Cày phim Hàn ba năm, KNOWLEDGE tiếng Hàn của tôi gồm đúng chữ "saranghae" và cách gọi oppa, keo lỳ.', 'Kiến thức, sự hiểu biết', 'beginner', 840),
  ('v423', 'lack', 'Bài thuyết trình nhóm tôi LACK đúng một thứ: người chịu làm slide, còn người góp ý thì dư, xu cà na.', 'Thiếu hụt', 'beginner', 810),
  ('v424', 'maintain', 'Tôi MAINTAIN chuỗi học tiếng Anh 200 ngày liên tục, toàn bằng cách mở app lúc 11 giờ 59 tối, slay.', 'Duy trì, giữ vững', 'beginner', 865),
  ('v425', 'nervous', 'Lần đầu thuyết trình trước cả phòng, tôi NERVOUS tới mức tự giới thiệu sai tên của chính mình, xỉu ngang.', 'Lo lắng, hồi hộp', 'beginner', 815),
  ('v426', 'opportunity', 'Crush hỏi "có ai về chung đường không", OPPORTUNITY ngàn năm có một, vậy mà tôi trả lời "tao đi xe buýt", hết cứu.', 'Cơ hội', 'beginner', 850),
  ('v427', 'prefer', 'Tôi PREFER nhắn tin hơn gọi điện, điện thoại mà reo là tim đập như bị gọi lên bảng.', 'Thích hơn', 'beginner', 820),
  ('v428', 'quality', 'Mua áo 50 nghìn ba cái, QUALITY đỉnh nóc kịch trần: giặt một lần là từ áo thun thành áo croptop.', 'Chất lượng, đặc tính', 'beginner', 805),
  ('v429', 'recognize', 'Họp lớp sau 5 năm, tôi không RECOGNIZE nổi đứa lớp trưởng, cho tới khi nó mở miệng nhắc đóng quỹ, ra đường tôi nể mỗi bạn.', 'Nhận ra, công nhận', 'beginner', 875),
  ('v430', 'sensitive', 'Răng tôi đang SENSITIVE, ăn kem thì ê buốt, mà bỏ kem thì tâm hồn còn ê buốt hơn, chằm zn.', 'Nhạy cảm', 'intermediate', 935),
  ('v431', 'trustworthy', 'Giao quỹ lớp cho đứa TRUSTWORTHY nhất nhóm, cuối kỳ nó báo cáo từng đồng kèm hóa đơn, flex nhẹ sự minh bạch.', 'Đáng tin cậy', 'intermediate', 925),
  ('v432', 'urgent', 'Group công ty báo "việc URGENT, vào gấp", vào thì thấy sếp hỏi trưa nay ai ăn cơm gà, ủa alo.', 'Khẩn cấp', 'beginner', 845),
  ('v433', 'valuable', 'Ở phòng trọ năm người, thứ VALUABLE nhất không phải laptop mà là cái ổ cắm còn trống lúc 11 giờ đêm, giành được là flex cả phòng.', 'Quý giá', 'beginner', 855),
  ('v434', 'particular', 'Tôi không kén ăn, chỉ có một yêu cầu PARTICULAR: trà sữa 30% đường, ít đá, thêm trân châu trắng.', 'Cụ thể, đặc biệt', 'intermediate', 910),
  ('v435', 'qualify', 'Tin tuyển thực tập sinh đòi 3 năm kinh nghiệm, đọc xong biết ngay mình khum QUALIFY cho cả vị trí thực tập.', 'Đủ điều kiện, đủ tư cách', 'intermediate', 940),
  ('v436', 'reasonable', 'Quán cơm gần trường giá REASONABLE, cơm thêm miễn phí, bà chủ keo lỳ tới mức cả lớp coi như mẹ nuôi tập thể.', 'Hợp lý, giá cả phải chăng', 'beginner', 855),
  ('v437', 'struggle', 'Tôi STRUGGLE với cái nắp hũ dưa cải mười phút, đưa đứa cùng phòng vặn một cái là mở, out trình.', 'Vật lộn, đấu tranh', 'beginner', 880),
  ('v438', 'thorough', 'Trước khi chốt đơn, tôi ô dề đọc review THOROUGH tới từng bình luận một sao, xong vẫn mua cái rẻ nhất.', 'Kỹ lưỡng, thấu đáo', 'intermediate', 960),
  ('v439', 'unique', 'Bạn tôi đặt tên mèo là Mì Tôm Trứng, cái tên UNIQUE tới mức bác sĩ thú y đọc tên cũng phải nhịn cười, slay.', 'Độc nhất, độc đáo', 'beginner', 860),
  ('v440', 'whisper', 'Trong rạp phim, đứa ngồi sau WHISPER với bồ nó mà nguyên hàng ghế đều biết luôn cái kết, ủa alo.', 'Thì thầm', 'beginner', 830)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v441', 'annoying', 'Tiếng muỗi vo ve lúc 2 giờ sáng là thứ ANNOYING nhất đời, bật đèn lên thì nó tàng hình.', 'Làm phiền, khó chịu', 'beginner', 820),
  ('v442', 'believe', 'Tôi vẫn BELIEVE cuối tuần này mình sẽ dọn phòng trọ, manifest đều đều, niềm tin đó đã sống khỏe suốt ba tháng nay.', 'Tin tưởng', 'beginner', 800),
  ('v443', 'critical', 'Thầy hướng dẫn CRITICAL với đề cương của tôi tới mức sửa luôn cả dấu chấm, tôi chằm zn hai ngày.', 'Quan trọng, nguy cấp, phê bình', 'intermediate', 970),
  ('v444', 'delighted', 'Sếp bảo nay về sớm, cả phòng DELIGHTED được đúng mười giây thì sếp nói thêm "nhớ mang laptop về".', 'Vui mừng, hài lòng', 'beginner', 890),
  ('v445', 'frustrated', 'Chụp 87 tấm mới được một tấm ưng, đăng lên bị app làm mờ, xu cà na thật, tôi FRUSTRATED tới mức xóa luôn app.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v446', 'genuine', 'Bạn GENUINE là đứa thấy mình đăng ảnh xấu thì nhắn riêng bảo xóa, chứ không vào khen "xinh quá" cho vui.', 'Thật lòng, chân thành', 'beginner', 880),
  ('v447', 'hesitate', 'Tôi HESITATE nửa tiếng trước nút thanh toán giỏ hàng 2 triệu, tới khi mã giảm giá hết hạn, vũ trụ quyết giùm luôn.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v448', 'influence', 'Bạn cùng phòng mở nhạc buồn mỗi tối, INFLUENCE tới mức tôi chưa thất tình mà cũng thấy cần chữa lành.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v449', 'urgent', 'Ba gọi lúc 6 giờ sáng bảo về quê gấp vì việc URGENT, về tới nơi thì ba nhờ đăng nhập lại Facebook.', 'Khẩn cấp', 'beginner', 845),
  ('v450', 'valuable', 'Trước mùa thi, cuốn vở ghi chép của đứa học giỏi nhất lớp còn VALUABLE hơn vàng, xin photo phải xếp hàng, fomo cả lớp.', 'Quý giá, có giá trị', 'beginner', 855),
  ('v451', 'appropriate', 'Đi phỏng vấn mặc hoodie in hình mèo, mẹ hỏi vậy có APPROPRIATE khum, tôi bảo đây là văn hóa startup.', 'Phù hợp, thích hợp', 'intermediate', 960),
  ('v452', 'behave', 'Về quê ăn Tết, mẹ dặn BEHAVE cho đàng hoàng, vậy mà cô Ba vừa hỏi lương bao nhiêu là tôi suýt báo thủ tại chỗ.', 'Cư xử, ăn ở', 'beginner', 820),
  ('v453', 'coincidence', 'Vừa đăng story than đói thì crush nhắn rủ ăn lẩu, nó bảo COINCIDENCE thôi mà tôi đã manifest tới đám cưới.', 'Sự trùng hợp ngẫu nhiên', 'intermediate', 980),
  ('v454', 'determined', 'Đăng ký gym 12 tháng, DETERMINED lắm, tới buổi thứ ba thì lý do nghỉ là trời hơi âm u, hết cứu.', 'Quyết tâm, kiên quyết', 'beginner', 880),
  ('v455', 'encourage', 'Cả group chat ENCOURAGE tôi nhắn tin cho crush, gửi xong thì cả lũ đồng loạt offline, red flag cả đám.', 'Khuyến khích, động viên', 'beginner', 860),
  ('v456', 'familiar', 'Mở đề thi thấy bài nào cũng FAMILIAR y như người yêu cũ: nhớ mặt mà không nhớ làm sao, chằm zn.', 'Quen thuộc', 'beginner', 810),
  ('v457', 'generous', 'Thằng keo lỳ nhất nhóm bỗng GENEROUS bao trà sữa cả phòng, hóa ra là để mọi người vote cho clip của nó.', 'Hào phóng, rộng lượng', 'beginner', 835),
  ('v458', 'hesitate', 'Đứng trước quầy trà sữa HESITATE mười phút giữa trân châu đen và trắng, quay lại thì quán hết cả hai, xu cà na.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v459', 'imitate', 'Em gái IMITATE y chang giọng tôi gọi cho mẹ xin tiền, mẹ chuyển khoản liền, giờ tôi mới là đứa bị nghi, báo thủ chính hiệu.', 'Bắt chước, nhại lại', 'intermediate', 940),
  ('v460', 'jealous', 'Thấy bạn cùng phòng được mẹ gửi lên nguyên thùng đồ ăn, tôi JEALOUS tới mức gọi về nhà nhắc khéo ba lần, ô dề ghê.', 'Ghen tị, ghen tuông', 'beginner', 830),
  ('v461', 'knowledgeable', 'Ông bạn KNOWLEDGEABLE về cà phê cỡ ngửi là biết hạt gì, vậy mà ra quán lần nào cũng gọi bạc xỉu thêm đường, ủa alo.', 'Am hiểu, có kiến thức rộng', 'intermediate', 950),
  ('v462', 'limit', 'Thẻ tín dụng thì có LIMIT, còn lòng tham của tôi mùa sale 11.11 thì khum.', 'Giới hạn', 'beginner', 815),
  ('v463', 'motivate', 'Nói real, thứ duy nhất MOTIVATE tôi dậy sớm là cái mã giảm 50% chỉ áp dụng trước 9 giờ sáng.', 'Thúc đẩy, tạo động lực', 'beginner', 860),
  ('v464', 'notice', 'Đi cà phê cả buổi mới NOTICE mình mang hai chiếc dép khác màu, đứa bạn thấy từ đầu mà im re ngồi chụp hình, ra đường tôi nể mỗi bạn.', 'Để ý thấy, nhận ra', 'beginner', 810),
  ('v465', 'obvious', 'Nó bảo không thích crush, nhưng tối nào cũng xem story người ta đầu tiên, OBVIOUS tới mức cả group khỏi cần check var.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v466', 'patient', 'Chờ shipper mười lăm phút vẫn PATIENT, tới khi app báo giao thành công mà trước cửa trống trơn là tới công chuyện.', 'Kiên nhẫn', 'beginner', 825),
  ('v467', 'quarrel', 'Hai đứa cùng phòng QUARREL suốt một tiếng xem ai rửa chén, cuối cùng gọi đồ ăn ngoài cho khỏi rửa, keo lỳ.', 'Cãi vã, tranh chấp', 'intermediate', 930),
  ('v468', 'reasonable', 'Quán cơm sau ký túc giá REASONABLE tới mức tôi nghi chủ quán đang làm dự án chữa lành sinh viên.', 'Hợp lý, phải chăng', 'beginner', 855),
  ('v469', 'stubborn', 'Cái laptop STUBBORN lắm, bấm cập nhật thì nhất quyết không chịu, đúng lúc nộp bài thì tự cập nhật 40 phút, thao túng tâm lý.', 'Bướng bỉnh, lỳ lợm', 'beginner', 860),
  ('v470', 'temporary', 'Ở phòng trọ không cửa sổ chỉ là TEMPORARY thôi, tôi tự nhủ vậy từ hồi năm nhất tới giờ đi làm năm hai, delulu.', 'Tạm thời', 'beginner', 870),
  ('v471', 'urgent', 'Group lớp ghi "URGENT, vào gấp", cả đám vào đủ thì lớp trưởng hỏi ai có sạc dự phòng cho mượn, ủa alo.', 'Khẩn cấp', 'beginner', 845),
  ('v472', 'vague', 'Hỏi cả nhóm chừng nào đi biển, nhận về câu ''để tính'', VAGUE cỡ này là kèo toang chắc rồi.', 'Mơ hồ, không rõ ràng', 'intermediate', 910),
  ('v473', 'willing', 'Cả nhóm rủ dậy 4 giờ sáng săn bình minh, tôi WILLING liền, gét gô, miễn có người chụp hộ còn tôi ngủ trên xe.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v474', 'accurate', 'Nhỏ bạn đoán drama nhà tôi ACCURATE hơn app thời tiết, nói trước ba ngày là xảy ra y chang, out trình.', 'Chính xác', 'beginner', 880),
  ('v475', 'believable', 'Bảo lớp trưởng quên nộp vì mạng rớt nghe còn BELIEVABLE, chứ bảo con mèo xóa file thì hơi xu cà na.', 'Có thể tin được', 'beginner', 815),
  ('v476', 'convenient', 'Ở trọ ngay trên tiệm tạp hóa CONVENIENT thật, mỗi tội đêm nào cũng xuống mua đồ ăn vặt, ví đang ét o ét.', 'Tiện lợi', 'beginner', 820),
  ('v477', 'dependable', 'Đứa DEPENDABLE nhất nhóm là đứa nhớ mang sạc dự phòng, ô, khăn giấy và cả tiền lẻ gửi xe, đỉnh nóc kịch trần.', 'Đáng tin cậy', 'intermediate', 930),
  ('v478', 'effective', 'Cách học thuộc bài EFFECTIVE nhất của tôi lowkey hơi kỳ: giảng lại cho con mèo nghe, nó ngủ, tôi thuộc.', 'Hiệu quả', 'beginner', 850),
  ('v479', 'grateful', 'Ví ét o ét, cuối tháng còn hai chục nghìn, tôi GRATEFUL với gói mì tôm cuối cùng như với ân nhân cứu mạng.', 'Biết ơn', 'beginner', 860),
  ('v480', 'honest', 'Nhỏ bạn hỏi tóc mới đẹp không, tôi HONEST khen đẹp, nó bảo nói thật đi, u là trời, biết đường nào mà sống.', 'Thành thật', 'beginner', 810)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v481', 'ignore', 'Group lớp nhắn 99+ tin, tôi IGNORE hết, tới khi thấy chữ ''điểm danh'' là đọc lại từ đầu trong ba giây.', 'Phớt lờ, lờ đi', 'beginner', 820),
  ('v482', 'intention', 'INTENTION ban đầu là vào app mua cục sạc, thoát app ra thì giỏ hàng có thêm cái đèn ngủ hình cây nấm, thao túng tâm lý.', 'Ý định, mục đích', 'intermediate', 910),
  ('v483', 'manage', 'Đi làm năm nhất, tôi MANAGE lương bằng cách chia năm cái hũ, tới ngày mười thì cả năm hũ cùng trống, toang.', 'Quản lý, xoay xở', 'beginner', 850),
  ('v484', 'necessary', 'Đi Đà Lạt ô dề mang sáu cái áo khoác, cái nào cũng NECESSARY, rốt cuộc mặc đúng một cái hoodie từ đầu tới cuối.', 'Cần thiết', 'beginner', 840),
  ('v485', 'optimistic', 'Bị từ chối lần thứ ba mà nó vẫn OPTIMISTIC, bảo crush đang test độ kiên trì, delulu cỡ này là có hệ thống.', 'Lạc quan', 'beginner', 840),
  ('v486', 'partial', 'Mẹ PARTIAL với con mèo ra mặt: nó làm vỡ ly thì là bé ngoan, tôi làm vỡ thì là báo thủ.', 'Một phần, thiên vị', 'beginner', 830),
  ('v487', 'quickly', 'Thấy tin ''tới cổng rồi'' là tôi trang điểm QUICKLY như đang thi chạy, ra tới nơi mới biết quên kẻ một bên mày, ét o ét.', 'Nhanh chóng', 'beginner', 800),
  ('v488', 'reaction', 'REACTION của ba khi thấy tôi nhuộm tóc hồng: im lặng ba giây, rồi hỏi có đổi lại được khum.', 'Phản ứng', 'beginner', 820),
  ('v489', 'significant', 'Đổi từ trà sữa full topping sang ít đường là bước tiến SIGNIFICANT, ít nhất tôi tự thấy mình slay.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v490', 'tolerate', 'Tôi TOLERATE được bạn cùng phòng ngáy, hát karaoke nửa đêm, nhưng ăn vụng mì của tôi là tới công chuyện.', 'Chịu đựng, tha thứ', 'beginner', 855),
  ('v491', 'utilize', 'Nhỏ bạn UTILIZE tối đa voucher, freeship với xu, đơn hai trăm nghìn mà chỉ trả ba chục, đúng là out trình.', 'Tận dụng, sử dụng', 'beginner', 860),
  ('v492', 'valid', 'Xin nghỉ vì đau bụng là lý do VALID, nhưng lỡ đăng ảnh check-in quán lẩu cùng ngày thì hết cứu.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v493', 'wonder', 'Lướt TikTok lúc 3 giờ sáng, tôi WONDER sao mình thuộc công thức làm bánh mà vẫn không biết nấu cơm, hết cứu.', 'Tự hỏi, băn khoăn', 'beginner', 810),
  ('v494', 'admit', 'Cãi nhau cả buổi về đường đi, cuối cùng nó ADMIT là mở nhầm bản đồ, lúc đó cả nhóm đã lạc sang tỉnh khác, tới công chuyện.', 'Thừa nhận', 'beginner', 865),
  ('v495', 'boring', 'Phim được review đỉnh nóc kịch trần mà BORING tới mức tôi ngủ gật, tỉnh dậy nhân vật vẫn đang ngồi uống trà.', 'Buồn chán', 'beginner', 800),
  ('v496', 'complain', 'Cả phòng COMPLAIN wifi chậm suốt ba tuần, tới khi check var mới phát hiện phòng bên đang ké mạng để cày phim.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v497', 'doubt', 'Áo hiệu giá 99 nghìn kèm freeship, tôi DOUBT ngay, rồi vẫn chốt đơn vì lỡ nó real thì sao.', 'Nghi ngờ', 'beginner', 855),
  ('v498', 'eager', 'Nghe có quán trà sữa mới gần trường, cả lớp fomo, EAGER rủ nhau đi, tới nơi thì hàng dài hơn cả hàng đăng ký tín chỉ.', 'Háo hức, hăm hở', 'intermediate', 920),
  ('v499', 'force', 'Hồi nhỏ mẹ FORCE tôi đi học bơi, giờ đi biển tôi là đứa duy nhất không phải ôm phao chụp hình, flex nhẹ.', 'Ép buộc', 'beginner', 840),
  ('v500', 'gather', 'Cả xóm trọ GATHER trước phòng số 3 lúc nửa đêm, tưởng hóng biến, hóa ra chủ phòng đang nấu mì cay.', 'Tụ họp, tập hợp', 'beginner', 830),
  ('v501', 'hardly', 'Từ hồi đi làm năm nhất, tôi HARDLY thấy mặt trời, đi lúc trời chưa sáng, về thì đèn đường đã bật, chằm zn.', 'Hầu như không', 'beginner', 815),
  ('v502', 'imagine', 'Ngồi IMAGINE cảnh crush rep tin nhắn trong năm phút, delulu thôi, thực tế là rep sau năm ngày bằng một cái like.', 'Tưởng tượng', 'beginner', 805),
  ('v503', 'kindness', 'Cô bán xôi đầu hẻm biết tôi ở trọ một mình nên hay cho thêm trứng, KINDNESS kiểu này chữa lành cả dạ dày lẫn tâm hồn.', 'Lòng tốt, sự tử tế', 'beginner', 820),
  ('v504', 'loose', 'Cái ghế ở quán cà phê LOOSE từ chân tới lưng, ngồi chill mà như đang tập thăng bằng, u là trời.', 'Lỏng, lỏng lẻo', 'beginner', 835),
  ('v505', 'mention', 'Lỡ MENTION người yêu cũ trong buổi họp lớp, cả bàn im bặt, rồi có đứa lặng lẽ mở story của người ta ra hóng biến.', 'Đề cập đến', 'beginner', 840),
  ('v506', 'notice', 'Đổi avatar từ hôm qua, mẹ NOTICE trước cả crush, còn nhắn hỏi sao ảnh này con trông ốm thế, ok mom.', 'Nhận ra, để ý thấy', 'beginner', 810),
  ('v507', 'offer', 'Công ty OFFER lương cao hơn chỗ cũ 2 triệu, đọc kỹ thì thấy dòng ''sẵn sàng làm cuối tuần'', red flag.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v508', 'perceive', 'Ba mẹ PERCEIVE việc tôi làm content là ngồi chơi điện thoại cả ngày, nói real thì cũng đúng một nửa.', 'Nhận thức, nhìn nhận', 'intermediate', 1010),
  ('v509', 'quality', 'Mua áo khoác 70 nghìn mà đòi QUALITY như hàng hiệu, giặt lần đầu nó co lại thành áo của em bé.', 'Chất lượng', 'beginner', 805),
  ('v510', 'recognize', 'Cắt tóc mái xong đi học, bác bảo vệ không RECOGNIZE nổi tôi, đòi xem thẻ sinh viên.', 'Nhận ra', 'beginner', 875),
  ('v511', 'sensitive', 'Răng tôi SENSITIVE tới mức uống trà đá phải nhai một bên, cắn kem một miếng là xỉu ngang.', 'Nhạy cảm', 'intermediate', 935),
  ('v512', 'trustworthy', 'Gửi mèo cho đứa TRUSTWORTHY nhất nhóm trông ba ngày, về thì mèo béo lên, còn nó lowkey thành fan cứng của con mèo.', 'Đáng tin cậy', 'intermediate', 925),
  ('v513', 'unexpected', 'Điều UNEXPECTED nhất buổi hẹn đầu: nguyên lớp đại học ngồi ngay bàn bên ăn cơm chó, có đứa còn vẫy tay chào.', 'Bất ngờ, không mong đợi', 'beginner', 850),
  ('v514', 'valuable', 'Món đồ VALUABLE nhất phòng trọ không phải laptop, mà là cái quạt duy nhất còn chịu quay đủ ba số, keo lỳ.', 'Quý giá, có giá trị', 'beginner', 855),
  ('v515', 'willing', 'Ai cần người xếp hàng mua vé concert, tôi WILLING liền, chỉ cần bao một ly trà chanh với cho sạc ké điện thoại, gét gô.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v516', 'annoying', 'Ủa alo, tiếng khoan tường nhà bên lúc 7 giờ sáng Chủ nhật ANNOYING kinh khủng, tôi nghi họ khoan thẳng vào giấc mơ của tôi.', 'Làm phiền, gây khó chịu', 'beginner', 820),
  ('v517', 'believable', 'Story ''đang ôn bài nghiêm túc'' sẽ BELIEVABLE hơn nếu góc ảnh không lộ cái tay cầm máy chơi game, check var là ra.', 'Có thể tin được', 'beginner', 815),
  ('v518', 'convenient', 'Mua nồi chiên không dầu xong mới thấy CONVENIENT thật, giờ tôi chiên luôn cả bánh mì, trứng với nỗi buồn.', 'Tiện lợi', 'beginner', 820),
  ('v519', 'doubt', 'Nó hứa mai trả tiền ăn lẩu, tôi DOUBT nhẹ, vì chữ mai của nó đã kéo dài từ học kỳ trước, red flag.', 'Nghi ngờ', 'beginner', 855),
  ('v520', 'efficient', 'Tôi học EFFICIENT nhất vào đêm trước hôm thi, nửa học kỳ gói gọn trong sáu tiếng và hai lon nước tăng lực, slay.', 'Hiệu quả, năng suất', 'intermediate', 920)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v521', 'frustrated', 'Canh săn vé concert từ 9 giờ, tới lượt thì web báo hết vé, FRUSTRATED tới mức muốn úp mặt vào bàn phím, kém miếng khó chịu.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v522', 'genuine', 'Lời khen GENUINE nhất tôi từng nhận là của chú bán bánh mì: ''con ăn khỏe vậy chú bán vui''.', 'Thật lòng, chân thành', 'beginner', 880),
  ('v523', 'hesitate', 'Thấy cái áo giảm 70% mà HESITATE đúng ba giây, quay lại thì hết size, fomo nguyên tuần.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v524', 'influence', 'Một video review trên TikTok INFLUENCE tôi fomo mua máy làm sữa hạt, giờ nó là cái kệ để chìa khóa đắt nhất nhà.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v525', 'judge', 'Mọi người hay JUDGE tôi vì mặc pijama đi siêu thị, chưa ai biết đó là bộ đồ đẹp nhất của tôi, slay.', 'Đánh giá, phán xét', 'beginner', 830),
  ('v526', 'lack', 'Bài thuyết trình nhóm tôi chẳng LACK thứ gì, slide có, nhạc nền có, chỉ thiếu đứa dám đứng lên nói, toang.', 'Thiếu hụt', 'beginner', 810),
  ('v527', 'maintain', 'MAINTAIN chuỗi học tiếng Anh 100 ngày liên tục, ngày 101 quên mở app, con cú xanh nhắn y như người yêu cũ, thao túng tâm lý.', 'Duy trì, giữ vững', 'beginner', 865),
  ('v528', 'nervous', 'Ngày đầu đi làm NERVOUS tới mức cúi chào luôn cái tượng ở sảnh, đồng nghiệp thấy nhưng giả vờ không thấy.', 'Lo lắng, hồi hộp', 'beginner', 815),
  ('v529', 'opportunity', 'Crush rủ đi xem phim đúng hôm tôi sốt, OPPORTUNITY ngàn năm có một mà tôi nằm đắp chăn nhìn trần nhà, xu cà na.', 'Cơ hội', 'beginner', 850),
  ('v530', 'prefer', 'Tối thứ Sáu tôi PREFER nằm nhà xem phim với gói snack hơn đi bar, nghe ô dề nhưng năm nay tôi chọn chữa lành.', 'Thích hơn', 'beginner', 820),
  ('v531', 'quality', 'Shop quảng cáo QUALITY cao cấp, nhận hàng thì cái túi da dính mưa một cái đã đổi sang màu khác, ủa alo.', 'Chất lượng', 'beginner', 805),
  ('v532', 'recognize', 'Họp lớp sau 5 năm, tôi không RECOGNIZE nổi lớp trưởng, cho tới khi nó mở miệng nhắc đóng quỹ, ra đường tôi nể mỗi bạn.', 'Nhận ra', 'beginner', 875),
  ('v533', 'urgent', 'Group chat bắn tin URGENT liên tục, vào hóng biến thì hóa ra cả bọn đang chọn quán lẩu tối nay.', 'Khẩn cấp', 'beginner', 845),
  ('v534', 'admit', 'Tôi phải ADMIT là cái nồi cơm điện mẹ bắt mang lên trọ đã cứu tôi khỏi ăn mì cả tháng, ok mom.', 'Thừa nhận', 'beginner', 865),
  ('v535', 'boring', 'Buổi đi chơi BORING nhất lowkey là hẹn nhau ra cà phê rồi mỗi đứa cắm mặt lướt điện thoại riêng ba tiếng.', 'Buồn chán', 'beginner', 800),
  ('v536', 'complain', 'Nó COMPLAIN suốt về chuyện ế, tới khi có người rủ đi date thì bảo hôm đó bận giặt đồ, hết cứu.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v537', 'force', 'Bạn thân FORCE tôi nhảy trend TikTok cùng, quay 30 lần mới xong, clip nổi nhất lại là cảnh tôi té, u là trời.', 'Ép buộc', 'beginner', 840),
  ('v538', 'hardly', 'Mua máy chạy bộ về phòng trọ xong tôi HARDLY đụng tới, giờ nó là cây phơi đồ xịn nhất xóm, flex nhẹ.', 'Hầu như không', 'beginner', 815),
  ('v539', 'offer', 'Quán lẩu mới OFFER combo bốn người giá ba người, cả nhóm bỗng nhớ ra là lâu lắm rồi chưa gặp nhau, gét gô.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v540', 'notice', 'Bạn cùng bàn NOTICE tôi ngáp tới lần thứ mười, lặng lẽ đẩy qua một ly cà phê sữa đá, tình bạn đỉnh nóc kịch trần.', 'Để ý thấy, nhận ra', 'beginner', 810)
